function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`visible${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6500);}
async function api(url,data){const r=await fetch(url,{credentials:'same-origin',...(data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session?.csrfToken||''},body:JSON.stringify(data)})});const result=await r.json();if(!r.ok){if(r.status===401){state=null;await signInScreen();}const error=new Error(result.error||'Request failed.');error.status=r.status;throw error;}return result;}
