  eventShareUI=null;const dialog=$('#detail-dialog');if(dialog?.open)dialog.close();if($('#detail-content'))$('#detail-content').textContent='';
  session=await(await fetch('/api/session',{credentials:'same-origin'})).json();document.body.classList.add('signed-out');
  $('#main').innerHTML=`<div class="login-layout"><section class="login-story"><a class="brand login-brand" href="/" aria-label="Big Red Buddy home"><span class="brand-mark" aria-hidden="true">BRB</span><span class="brand-name">Big Red<br>Buddy</span></a>${heading('BUILT FOR LIFE AT CORNELL TECH','Your week.<br>A little clearer.','Classes, Product Studio, campus life, and your next opportunity. Bring the moving parts into focus.')}<div class="login-features"><div><span>01</span><p><strong>Stay ahead of your coursework.</strong>Turn a syllabus into dates you can trace and review.</p></div><div><span>02</span><p><strong>Keep the right things close.</strong>Connect your calendar, Telegram, and Studio updates.</p></div><div><span>03</span><p><strong>Make space for what is next.</strong>Find relevant roles and prepare answers from your resume.</p></div></div></section><section class="panel login-panel" aria-labelledby="login-heading"><div class="panel-body"><span class="tag">YOUR STUDENT WORKSPACE</span><h2 id="login-heading">Welcome to Big Red Buddy.</h2><p>Sign in to organize your own sources, schedule, and connected accounts.</p>${session.googleConfigured?'<a class="button login-cta" href="/auth/google/start">Continue with Cornell Google ↗</a>':'<p class="notice">Google sign-in is awaiting operator configuration.</p>'}${session.devEnabled?`<div class="dev-signin"><p class="form-help"><strong>Local development preview</strong><br>These identities are for local testing and are not verified Google sign-ins.</p>${session.devEmails.map(email=>`<button class="button secondary" data-action="dev-signin" data-email="${esc(email)}">${esc(email)}</button>`).join('')}</div>`:''}<div class="login-privacy"><span aria-hidden="true">↳</span><p>Your workspace is scoped to your student account. Calendar and Slack access require separate consent.</p></div><p class="form-help">Independent class prototype. Cornell Tech has not endorsed this app.</p></div></section></div>`;
