async function bootstrap(){session=await api('/api/session');if(!session.user){await signInScreen();return;}document.body.classList.remove('signed-out');$('#user-name').textContent=session.user.name||session.user.email;document.querySelectorAll('.avatar').forEach(el=>el.textContent=(session.user.name||session.user.email).slice(0,2).toUpperCase());await load();health=await api('/api/health');updateHealth();if(page==='connections')render();}
async function load(renderPage=true){const owner=session;const next=await api('/api/state');if(session!==owner)return;state=next;if(session.pilotAccessAdmin){const access=await api('/api/pilot-access').catch(()=>({error:'Could not read invitation sync status.'}));if(session!==owner)return;pilotAccessStatus=access;}if(renderPage)render();}
async function action(fn){if(busy)return;busy=true;try{await fn();await load();}catch(e){toast(e.message,true);}finally{busy=false;}}
async function runTask(url,data,onDone){const {taskId}=await api(url,data);toast('Queued securely. You can keep using your workspace.');const started=Date.now();const timer=setInterval(async()=>{try{const tasks=await api('/api/tasks');const t=tasks.find(t=>t.id===taskId);if(t?.status==='done'||t?.status==='error'){clearInterval(timer);if(t.status==='error')toast(t.error,true);else{await load();toast('Completed.');if(onDone)onDone(t.result);}}else if(Date.now()-started>240000){clearInterval(timer);toast('Still processing. Check connection status and refresh shortly.',true);}}catch{clearInterval(timer);toast('Lost connection. Your queued work remains stored.',true);}},1500);}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
const btn=(label,action,cls='secondary',extra='')=>`<button class="button ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function empty(title,description,symbol='◎'){return `<div class="empty"><span class="empty-symbol">${symbol}</span><strong>${title}</strong>${description}</div>`;}
function eventRows(events,{reviewOnly=false}={}){return events.map(e=>`<tr><td data-label="Select"><input type="checkbox" class="event-check" value="${esc(e.id)}" aria-label="Select ${esc(e.title)}" ${(reviewOnly?!academicReviewable(e):!e.start||e.evidenceVerified===false||e.cancelled)?'disabled':''}></td><td data-label="Item / source"><span class="title">${esc(e.title)}</span><span class="secondary-text">${esc(e.sourceName)}${e.page?' · p. '+e.page:''}</span></td><td data-label="New York time">${fullDate(e)}<span class="secondary-text">${Number.isFinite(Date.parse(e.start))?timeFmt.format(new Date(e.start)):'Time unspecified'}</span></td><td data-label="Location">${esc(e.location||'Not published')}</td><td data-label="Status">${badge(e)}</td><td data-label="Evidence">${btn('View source','detail','quiet',`data-id="${esc(e.id)}"`)}</td></tr>`).join('');}
function eventTable(events){return `<div class="panel"><div class="table-actions"><label class="select-all-control"><input type="checkbox" id="select-all" aria-label="Select all schedulable items"><span>Select all</span></label><span class="selection-label"><span id="selection-count" aria-live="polite">0 selected</span> · Review sources before approval</span>${btn('Approve selected','approve','small','data-selection-action disabled')}${btn('Dismiss selected','dismiss','secondary small','data-selection-action disabled')}</div><div class="table-wrap" tabindex="0" role="region" aria-label="Imported schedule"><table><caption class="sr-only">Imported events with source, date, location, and review status</caption><thead><tr><th scope="col">Select</th><th scope="col">Item / source</th><th scope="col">New York time</th><th scope="col">Location</th><th scope="col">Status</th><th scope="col">Evidence</th></tr></thead><tbody>${eventRows(events)}</tbody></table></div>${events.length?'':empty('Nothing here yet','Upload a syllabus or connect a source to get started.','▤')}</div>`;}
function tabs(events=state.events){return `<div class="page-tabs"><button data-filter="upcoming" aria-pressed="${filter==='upcoming'}" class="${filter==='upcoming'?'active':''}">Upcoming</button><button data-filter="review" aria-pressed="${filter==='review'}" class="${filter==='review'?'active':''}">Needs review <span class="count-pill">${events.filter(e=>e.status==='review'&&!e.cancelled).length}</span></button><button data-filter="all" aria-pressed="${filter==='all'}" class="${filter==='all'?'active':''}">All imported</button><span class="right">America/New_York · source dates</span></div>`;}
function academicReviewable(event){
 if(event.status!=='review'||event.cancelled||event.evidenceVerified===false||!Number.isFinite(Date.parse(event.start))||!Number.isFinite(Date.parse(event.end))||Date.parse(event.end)<=Date.parse(event.start))return false;
 const localDate=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(event.start));
 return event.date===localDate;
}
function scheduleDate(value){const date=new Date(`${value}T12:00:00Z`);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('en-US',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric'}).format(date):'Date to confirm';}
function scheduleClock(value){if(!/^\d{2}:\d{2}$/.test(value||''))return 'Time to confirm';const [hour,minute]=value.split(':').map(Number);return `${hour%12||12}:${String(minute).padStart(2,'0')} ${hour<12?'AM':'PM'}`;}
function schedulePatternView(pattern){
 const days={Mon:'Mondays',Tue:'Tuesdays',Wed:'Wednesdays',Thu:'Thursdays',Fri:'Fridays',Sat:'Saturdays',Sun:'Sundays'};
 const weekly=pattern.weekdays.map(day=>days[day]||day).join(' & '),single=pattern.dates.length===1;
 const label=pattern.invalidCount?'Dates or times need review':single?scheduleDate(pattern.firstDate):`${weekly}${pattern.missingDates.length||pattern.gapCheckLimited?' · selected dates':''}`;
 return `<li class="schedule-pattern"><div><strong>${esc(label)}</strong><span class="schedule-time">${esc(scheduleClock(pattern.startTime))}${pattern.endTime?` – ${esc(scheduleClock(pattern.endTime))}${pattern.endDayOffset?` (+${pattern.endDayOffset} day${pattern.endDayOffset===1?'':'s'})`:''}`:''}</span></div><div class="schedule-pattern-meta"><span>${esc(pattern.location||'Room not published')}</span>${!single?`<span>${esc(scheduleDate(pattern.firstDate))} – ${esc(scheduleDate(pattern.lastDate))}</span>`:''}<span>${pattern.events.length} meeting${pattern.events.length===1?'':'s'}</span></div>${pattern.missingDates.length?`<p class="schedule-exceptions">No meeting in this pattern on ${pattern.missingDates.map(date=>esc(scheduleDate(date))).join(', ')}. Check breaks or alternate times below; these dates will not be added.</p>`:''}</li>`;
}
function scheduleDatesTable(events){return `<div class="table-wrap" tabindex="0" role="region" aria-label="Imported schedule"><table><caption class="sr-only">Imported events with source, date, location, and review status</caption><thead><tr><th scope="col">Select</th><th scope="col">Item / source</th><th scope="col">New York time</th><th scope="col">Location</th><th scope="col">Status</th><th scope="col">Evidence</th></tr></thead><tbody>${eventRows(events,{reviewOnly:true})}</tbody></table></div>`;}
function academicScheduleView(events){
 if(typeof groupClassSchedules!=='function')return eventTable(events);
 const groups=groupClassSchedules(events),deadlines=events.filter(event=>event.kind!=='class'),eligible=events.filter(academicReviewable).length;
 return `<section class="panel academic-schedule" aria-labelledby="schedule-heading"><div class="panel-head"><div><h2 id="schedule-heading">Your class schedule</h2><p class="form-help">${groups.length} class${groups.length===1?'':'es'} · ${events.filter(e=>e.kind==='class').length} meeting dates${deadlines.length?` · ${deadlines.length} deadline${deadlines.length===1?'':'s'}`:''}. Grouped from the dates in this view. Times are in New York.</p></div><span class="tag">BY CLASS</span></div><div class="table-actions"><label class="select-all-control"><input type="checkbox" id="select-all" aria-label="Select all dates ready for review" ${eligible?'':'disabled'}><span>Select all ready for review</span></label><span class="selection-label"><span id="selection-count" aria-live="polite">0 dates selected</span></span>${btn('Approve selected','approve','small','data-selection-action disabled')}${btn('Dismiss selected','dismiss','secondary small','data-selection-action disabled')}</div><p class="schedule-review-help">Select a class to review its ready dates together. Expand it to check individual dates and source evidence. Already-reviewed dates stay unchanged.</p>
 <div class="class-schedule-list">${groups.map((group,index)=>{
  const ready=group.events.filter(academicReviewable).length,reviewed=group.events.filter(e=>e.status==='approved'&&!e.cancelled).length,blocked=group.events.filter(e=>e.status==='review'&&!academicReviewable(e)).length;
  return `<article class="class-schedule-card" data-schedule-group="${index}" aria-labelledby="class-schedule-${index}"><div class="class-schedule-heading"><div><h3 id="class-schedule-${index}">${esc(group.title)}</h3><p>${esc(group.sourceName||'Imported class')}${group.term&&!group.sourceName?.includes(group.term)?` · ${esc(group.term)}`:''}</p></div><span class="tag ${reviewed===group.events.length?'green':ready||blocked?'amber':'muted'}">${reviewed===group.events.length?'✓ Reviewed':ready?`${ready} ready for review`:blocked?'Needs attention':'No dates to approve'}</span></div><ul class="schedule-patterns">${group.patterns.map(schedulePatternView).join('')}</ul><div class="class-schedule-footer"><label class="checkbox-control"><input type="checkbox" class="class-schedule-check" aria-label="Select ready dates for ${esc(group.title)}" ${ready?'':'disabled'}><span>${ready?`Select ${ready} date${ready===1?'':'s'} for review`:reviewed===group.events.length?'All dates reviewed':'No dates ready for review'}</span></label>${reviewed&&reviewed!==group.events.length?`<span class="form-help">${reviewed} already reviewed</span>`:''}${blocked?`<span class="course-error">${blocked} date${blocked===1?'':'s'} need${blocked===1?'s':''} attention below</span>`:''}</div><details class="class-schedule-details"><summary>View ${group.events.length} meeting date${group.events.length===1?'':'s'} & sources</summary>${scheduleDatesTable(group.events)}</details></article>`;
 }).join('')}</div>${deadlines.length?`<div class="schedule-deadline-heading"><h3>Assignments, quizzes & exams</h3><p>Review each deadline separately.</p></div>${scheduleDatesTable(deadlines)}`:''}${events.length?'':empty('No dates in this view','Choose another tab or add your schedule and syllabus.','▤')}</section>`;
}
function selectedScheduleIds(){return [...new Set([...document.querySelectorAll('.event-check')].filter(checkbox=>checkbox.checked&&!checkbox.disabled).map(checkbox=>checkbox.value))];}
function scheduleReviewSnapshot(event){return Object.fromEntries(['id','title','kind','date','start','end','location','status','cancelled','evidenceVerified','evidence','updatedAt','sourceId'].map(key=>[key,event[key]??null]));}
function updateScheduleSelection(){
 const academic=$('.academic-schedule'),ids=selectedScheduleIds(),all=[...document.querySelectorAll('.event-check:not(:disabled)')];
 for(const card of document.querySelectorAll('.class-schedule-card')){const children=[...card.querySelectorAll('.event-check:not(:disabled)')],selected=children.filter(c=>c.checked).length,control=card.querySelector('.class-schedule-check');control.checked=children.length>0&&selected===children.length;control.indeterminate=selected>0&&selected<children.length;}
 const selectAll=$('#select-all');if(selectAll){selectAll.checked=all.length>0&&ids.length===all.length;selectAll.indeterminate=ids.length>0&&ids.length<all.length;}
 const label=$('#selection-count');if(label)label.textContent=academic?`${ids.length} date${ids.length===1?'':'s'} selected${ids.length>200?' · Select up to 200 at a time':''}`:`${ids.length} selected`;
 document.querySelectorAll('[data-selection-action]').forEach(button=>button.disabled=ids.length===0||ids.length>200);
}
function filtered(events){return events.filter(e=>filter==='all'||filter==='review'?filter==='all'||e.status==='review':e.date>=currentDate()&&e.status!=='dismissed'&&!e.cancelled);}
function overview(){
  const next=upcoming().sort((a,b)=>(a.start||`${a.date}T23:59:59Z`).localeCompare(b.start||`${b.date}T23:59:59Z`));
  const reviews=next.filter(e=>e.status==='review'),missingTimes=reviews.filter(e=>!e.start).length;
  const nextTimed=next.find(e=>e.start&&Date.parse(e.start)>=Date.parse(state.now));
  const weekEnd=new Date(Date.parse(state.now)+7*86400000).toISOString().slice(0,10),week=next.filter(e=>e.date<=weekEnd);
  const connections=[state.connections.telegram.linked,state.connections.google.connected,!!state.connections.slack.health?.lastSuccess].filter(Boolean).length;
  const primary=reviews.length?btn('Review next date →','detail','',`data-id="${esc(reviews[0].id)}"`):!state.sources.length?btn('Upload your syllabus','upload-syllabus',''):btn('Upload another syllabus','upload-syllabus','');
  const stats=[['Classes this week',week.filter(e=>e.kind==='class').length,'From your imported sources'],['Deadlines this week',week.filter(e=>['assignment','studio','quiz','exam'].includes(e.kind)).length,'Review before reminders'],['Connected accounts',`${connections} / 3`,'Calendar, Telegram, Slack'],['Dates reviewed',state.events.filter(e=>e.status==='approved').length,'Across your imported schedule']];
  const reminderNote=state.profile.paused?'Reminders are paused.':!state.connections.telegram.linked?'Telegram is not linked.':null;
  return heading('YOUR CORNELL TECH WORKSPACE','Your week, in focus.','Know what is next. Check what matters. Make room for the rest.',primary+(state.sources.length?btn('Export calendar','export','secondary'):''))+
  `<div class="focus-grid">
    <section class="panel review-focus" aria-labelledby="review-heading"><div class="panel-body">
      <div class="focus-heading"><div><div class="eyebrow">START HERE</div><h2 id="review-heading">${reviews.length?'A few dates need your eye.':state.events.length?(next.length?'Upcoming dates are reviewed.':'No upcoming dates to review.'):'Bring your first week together.'}</h2></div><span class="review-total" role="status" aria-label="${reviews.length} upcoming dates need review">${reviews.length}</span></div>
      <p class="focus-intro">${reviews.length?`${reviews.length} upcoming ${reviews.length===1?'item is':'items are'} waiting for review.${missingTimes?` ${missingTimes} ${missingTimes===1?'needs a confirmed time':'need confirmed times'}.`:' Check the source before turning on reminders.'}`:state.events.length?'Keep checking original sources for changes and anything not imported.':'Upload a syllabus, check the extracted dates, then connect reminders.'}</p>
      <div class="review-list">${reviews.slice(0,3).map(e=>`<div class="review-item"><span class="review-icon" aria-hidden="true">${e.start?'↳':'!'}</span><div><h3>${esc(e.title)}</h3><p>${fullDate(e)} · ${e.start?timeFmt.format(new Date(e.start)):'Time not specified'}<br><span>${esc(e.sourceName||'Imported source')}</span></p></div>${btn(e.start?'Review':'Add time','detail','quiet',`data-id="${esc(e.id)}" aria-label="${esc(e.start?'Review '+e.title:'Confirm time for '+e.title)}"`)}</div>`).join('')||`<div class="focus-empty"><span aria-hidden="true">${state.events.length?'✓':'01'}</span><p>${state.events.length?(next.length?'Reviewed dates can be exported. Check your connections before relying on reminders.':'Past imported records are still available in Academics. Check your sources for upcoming obligations.'):'Start with one course. Every extracted date stays linked to its source.'}</p></div>`}</div>
      <div class="focus-footer">${reviews.length>3?`${reviews.length-3} more ${reviews.length-3===1?'date':'dates'} will follow as you review.`:'Your sources stay attached to every date.'}</div>
    </div></section>
    <section class="panel next-focus" aria-labelledby="next-heading"><div class="panel-body"><div class="focus-kicker">NEXT TIMED ITEM <span>NEW YORK TIME</span></div>
      ${nextTimed?`${badge(nextTimed)}<h2 id="next-heading" class="next-title">${esc(nextTimed.title)}</h2><div class="next-when"><span class="next-date">${fullDate(nextTimed)}</span><span class="next-time">${timeFmt.format(new Date(nextTimed.start))}</span></div><div class="next-location"><span>LOCATION</span><strong>${esc(nextTimed.location||'Not published')}</strong></div><p class="next-source">${esc(nextTimed.sourceName||'Imported source')}${nextTimed.page?' · page '+nextTimed.page:''}</p><div class="focus-footer">${btn('View source →','detail','quiet',`data-id="${esc(nextTimed.id)}"`)}</div>`:`<h2 id="next-heading" class="next-title">Your next commitment will appear here.</h2><p class="next-source">Import a source and confirm its dates. Missing information stays visible.</p><div class="next-location"><span>YOUR NEXT STEP</span><strong>${missingTimes?'Resolve the missing times.':state.sources.length?'Check your source coverage.':'Add your syllabus.'}</strong></div>`}
    </div></section>
  </div>
  ${reminderNote?`<div class="notice delivery-note"><strong>${reminderNote}</strong> <span>Review your dates and check your connections to receive alerts.</span><a href="#connections">Manage reminders →</a></div>`:''}
  <div class="summary-grid overview-stats" role="group" aria-label="Your week at a glance">${stats.map(([label,value,note])=>`<div class="stat"><div class="stat-top">${label}</div><div class="stat-value">${value}</div><div class="stat-bottom">${note}</div></div>`).join('')}</div>
  <div class="overview-grid"><div>
    <section class="panel"><div class="panel-head"><h2>Coming up<span class="sub">Your next few imported commitments</span></h2><a href="#academics">Open academics ↗</a></div><div class="panel-body"><div class="section-caption">THE DAYS AHEAD</div>${next.slice(0,5).map(e=>`<div class="agenda-row"><div class="agenda-time">${fullDate(e)}<small>${e.start?timeFmt.format(new Date(e.start)):'Time needed'}</small></div><div class="agenda-content"><h3>${esc(e.title)}</h3><p>${esc(e.location||'Location not published')}<br>${esc(e.sourceName||'Imported source')}</p>${badge(e)}</div></div>`).join('')||empty('A little structure starts here','Import a syllabus to see your next commitments.')}</div><div class="card-note">Reminders need reviewed dates and confirmed times. Imported coverage may be incomplete.</div></section>
    <div class="studio-strip"><span class="strip-icon" aria-hidden="true">⌘</span><div><h3>Keep Product Studio close.</h3><p>Announcements, deliverables, and the original source.</p></div><a href="#studio">Open Studio ↗</a></div>
  </div><div>
    <section class="panel assistant-panel"><div class="panel-head"><div class="assistant-heading"><span class="assistant-star" aria-hidden="true">✧</span><h2>Ask your assistant</h2></div><span class="tag">PRIVATE MODEL</span></div><div class="panel-body"><p>Hi ${esc(state.profile.name)}. Ask about your imported schedule. Answers stay grounded in your own sources.</p><form id="chat-form" class="chat-box"><label for="assistant-question" class="sr-only">Ask about your schedule</label><input id="assistant-question" name="question" required maxlength="2000" placeholder="What is due this week?"><button class="button" aria-label="Send question">↑</button></form><div id="chat-answer" class="chat-answer" aria-live="polite"></div><div class="assistant-foot"><span>Check cited dates against the source.</span></div></div></section>
    <section class="panel"><div class="panel-head"><h2>Your connections</h2><a href="#connections">Manage ↗</a></div><div class="panel-body">${connectionRows()}</div><div class="card-note">${state.profile.paused?'Reminders paused.':'Check service status before relying on reminders.'}</div></section>
  </div></div>`;
}
function connectionRows(){return [['▤','Syllabus',state.sources.some(s=>s.type==='syllabus'),'Imported'],['◷','Google Calendar',state.connections.google.connected,'Connected'],['↗','Telegram',state.connections.telegram.linked,'Linked'],['⌘','Product Studio Slack',!!state.connections.slack.health?.lastSuccess||state.connections.slack.socket?.connected,'Connected']].map(([icon,name,on,label])=>`<div class="connection-row"><span class="service-icon">${icon}</span><span>${name}</span><span class="status-dot ${on?'on':''}">${on?label:'Setup needed'}</span></div>`).join('');}
const candidateKey=c=>JSON.stringify([c.courseId,c.sectionId]);
const candidateCanImport=c=>c.importable===true&&!['dropped','waitlisted','wait-listed','cart','withdrawn'].includes(String(c.enrollmentStatus||'').toLowerCase());
const matchDescription=value=>({'exact-course-and-class-number':'Exact course and class number','exact-course-and-section':'Exact course and section'}[value]||value||'Recognized course details');
function enrollmentView(){
 const e=enrollment,locked=e.uploading||e.confirming,pending=e.proposals.filter(p=>p.status==='review');
 return `<section id="enrollment-import" class="panel enrollment-import" aria-labelledby="enrollment-heading"><div class="panel-head"><h2 id="enrollment-heading">Import enrollment screenshot/PDF<span class="sub">Recognize course details, then choose which classes to add.</span></h2><span class="tag">REVIEW REQUIRED</span></div><div class="panel-body">
 <p>Upload a clear enrollment PDF or photo. A catalog match does not verify enrollment: check each course is enrolled, rather than dropped, waitlisted, or in your cart. Nothing is added until you select and confirm it.</p>
 <div class="enrollment-upload"><div class="field"><label for="enrollment-term">Term shown on your document</label><select id="enrollment-term" ${locked?'disabled':''}><option value="" ${e.term?'':'selected'}>Choose a term</option><option value="FA26" ${e.term==='FA26'?'selected':''}>Fall 2026</option><option value="SP27" ${e.term==='SP27'?'selected':''}>Spring 2027</option></select></div><div class="form-actions">${btn(e.uploading?'Uploading…':'Choose enrollment PDF or photo','upload-enrollment','',locked?'disabled':'')}${btn('Take a photo','camera-enrollment','secondary',locked?'disabled':'')}</div></div>
 <input id="enrollment-file" type="file" accept="application/pdf,image/png,image/jpeg" hidden><input id="enrollment-camera" type="file" accept="image/jpeg,image/png" capture="environment" hidden>
 <p class="form-help">PDF, PNG, or JPEG · maximum 12 MB. Crop out information you do not need to share. The camera option depends on your device. Upload syllabi separately for assignments and exams.</p>
 <p class="form-help">Using your linked Telegram chat? Send <code>/enrollment FA26</code> or <code>/enrollment SP27</code>, then send the enrollment PDF or photo. The bot will ask you to select and confirm your enrolled classes.</p>
 <div id="enrollment-status" role="status">${e.error?`<p class="course-error">${esc(e.error)}</p>`:''}${e.notice?`<p>${esc(e.notice)}</p>`:''}${e.loading?'<p>Loading documents waiting for review…</p>':''}</div>
 <div class="enrollment-review-heading"><h3>Check your matches</h3>${btn(e.loading?'Refreshing…':'Refresh matches','refresh-enrollment','quiet',e.loading||locked?'disabled':'')}</div>
 ${pending.map((proposal,pi)=>{const selected=e.selections[proposal.id]||[],count=proposal.candidates.filter(c=>candidateCanImport(c)&&selected.includes(candidateKey(c))).length,blocked=proposal.canConfirm===false||!!proposal.blockedReason;return `<article class="enrollment-proposal" aria-labelledby="enrollment-proposal-${pi}"><h3 id="enrollment-proposal-${pi}">${esc(proposal.sourceName||'Enrollment document')}</h3><p class="form-help">${esc(proposal.term)} · Check every selected class against your original document.${proposal.snapshotFetchedAt?` Catalog snapshot: ${esc(catalogDate(proposal.snapshotFetchedAt))}; not a live schedule.`:''}</p>
 ${proposal.warnings?.length?`<ul class="course-warnings">${proposal.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}${proposal.blockedReason?`<p class="course-error">${esc(proposal.blockedReason)}</p>`:''}
 <fieldset class="enrollment-candidates" ${locked?'disabled':''}><legend>Select only classes you are enrolled in</legend>${proposal.candidates.map((c,ci)=>{const allowed=candidateCanImport(c),unknown=!c.enrollmentStatus||c.enrollmentStatus==='unknown';return `<label class="enrollment-candidate" for="enrollment-candidate-${pi}-${ci}"><input id="enrollment-candidate-${pi}-${ci}" type="checkbox" data-enrollment-proposal="${esc(proposal.id)}" data-candidate-key="${esc(candidateKey(c))}" ${allowed&&!blocked?'':'disabled'} ${selected.includes(candidateKey(c))?'checked':''}><span><strong>${esc(c.code)} · ${esc(c.name)}</strong><span>${esc(c.label||c.sectionId)}</span><span>${esc(c.meetingsSummary||'Check the published meeting times in the course source before confirming.')}</span><span>${esc(c.location||'Room not published — confirm before attending.')}</span><span class="enrollment-match">Matched by: ${esc(matchDescription(c.matchBasis))}</span><span class="${unknown?'course-error':'enrollment-match'}">${unknown?'Enrollment status not readable — check this is an enrolled class, not dropped or waitlisted.':`Document enrollment status: ${esc(c.enrollmentStatus)}`}</span>${c.sourceUrl||c.courseUrl?`<a href="${link(c.courseUrl||c.sourceUrl)}" target="_blank" rel="noreferrer">Check course source ↗</a>`:''}${c.warnings?.length?`<span class="enrollment-warnings">${c.warnings.map(w=>esc(w)).join(' · ')}</span>`:''}${!allowed?`<span class="course-error">${esc(c.blockedReason||'This match cannot be added. Resolve its enrollment or meeting details first.')}</span>`:''}</span></label>`;}).join('')||'<p>No exact sections could be matched. Use the course picker below.</p>'}</fieldset>
 ${proposal.unmatched?.length?`<div class="enrollment-unmatched"><strong>Not included in this import</strong><ul>${proposal.unmatched.map(item=>`<li>${esc(typeof item==='string'?item:item.text||item.code||'Unmatched entry')}${typeof item==='object'&&item.reason?` — ${esc(item.reason)}`:''}</li>`).join('')}</ul><p>Use the course picker below to resolve these items. They will not be added by confirmation.</p></div>`:''}
 <div class="form-actions"><span class="enrollment-count" role="status">${count} selected</span>${btn(e.confirming?'Adding selected classes…':state.connections.google.connected?'Confirm these classes and add to calendar':'Confirm these classes and add to my schedule','confirm-enrollment','',`data-id="${esc(proposal.id)}" ${!count||count>20||locked||blocked?'disabled':''}`)}</div><p class="form-help">Select up to 20 classes. Confirmation approves only checked sections and their published meetings. It does not enroll you in Cornell courses or remove previously imported classes. Catalog changes are not monitored automatically.</p></article>`;}).join('')||(!e.loading&&e.loaded?`<p class="form-help">${e.analyzing?'Recognition is still queued or processing. Refresh matches after it finishes.':'No enrollment documents are waiting for review.'}</p>`:'')}
 ${e.receipt?`<div class="enrollment-receipt course-receipt" role="status" tabindex="-1"><h3>Selected classes saved</h3><p>${esc(e.receipt.imported||0)} meetings added · ${esc(e.receipt.reused||0)} existing meetings reused · ${esc(e.receipt.skipped||0)} excluded occurrences skipped.</p><p>${esc(e.receipt.calendarStatus)}</p>${e.receipt.warnings?.length?`<ul class="course-warnings">${e.receipt.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<p>Next, upload your syllabi to add assignments, quizzes, and exams for review.</p>${btn('Upload syllabus','upload-syllabus','secondary')}</div>`:''}
 </div></section>`;
}
function refreshEnrollmentView(focusId){if(page!=='academics'||!state)return;const element=$('#enrollment-import');if(element)element.outerHTML=enrollmentView();if(focusId)document.getElementById(focusId)?.focus();}
async function fetchEnrollmentProposals(){const e=enrollment;if(e.loading)return;e.loading=true;e.error='';refreshEnrollmentView();try{const proposals=await api('/api/enrollment/proposals');if(enrollment!==e)return;if(!Array.isArray(proposals))throw new Error('Enrollment review is unavailable. Try refreshing matches.');e.proposals=proposals;e.selections={};e.loaded=true;}catch(error){if(enrollment===e){e.error=error.message;e.loaded=true;}}finally{e.loading=false;if(enrollment===e)refreshEnrollmentView();}}
function watchFeatureTask(taskId,{active,onDone,onError}){const student=session.user.id,started=Date.now();let checking=false;const timer=setInterval(async()=>{if(!active()||session?.user?.id!==student){clearInterval(timer);return;}if(Date.now()-started>240000){clearInterval(timer);onError('The task is still pending. Refresh to check its progress; it may continue in the background.');return;}if(checking)return;checking=true;try{const tasks=await api('/api/tasks');if(!active()||session?.user?.id!==student)return;const task=tasks.find(t=>t.id===taskId);if(task?.status==='done'){clearInterval(timer);await onDone(task.result);}else if(task?.status==='error'){clearInterval(timer);onError(task.error||'The task needs attention.');}}catch(error){clearInterval(timer);if(active())onError(error.message||'Could not check task status.');}finally{checking=false;}},1500);}
async function uploadEnrollment(file){
 const e=enrollment;if(!file||e.uploading||e.confirming)return;e.error='';
 if(!['FA26','SP27'].includes(e.term)){e.error='Choose the term shown on your enrollment document first.';refreshEnrollmentView('enrollment-term');return;}
 const mimeType=file.type||(/\.pdf$/i.test(file.name)?'application/pdf':/\.png$/i.test(file.name)?'image/png':/\.jpe?g$/i.test(file.name)?'image/jpeg':'');
 if(!['application/pdf','image/png','image/jpeg'].includes(mimeType)||file.size>12*1024*1024){e.error='Choose a PDF, PNG, or JPEG no larger than 12 MB.';refreshEnrollmentView();return;}
 e.uploading=true;e.notice='Uploading for recognition. No classes will be added yet.';const term=e.term;refreshEnrollmentView();
 try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Could not read this file. Choose it again.'));reader.readAsDataURL(file);});if(enrollment!==e)return;const result=await api('/api/enrollment/analyze',{base64,mimeType,name:file.name,term});if(enrollment!==e)return;e.analyzing=true;e.notice='Recognition queued. You can keep working; review the matched classes here when it finishes.';watchFeatureTask(result.taskId,{active:()=>enrollment===e,onDone:async()=>{e.analyzing=false;e.notice='Recognition finished. Select only the classes you are enrolled in, then confirm.';await fetchEnrollmentProposals();},onError:message=>{e.analyzing=false;e.error=message;e.notice='No classes were added by recognition. Refresh matches or try another document.';refreshEnrollmentView();}});}
 catch(error){if(enrollment===e){e.error=error.message;e.notice='';}}
 finally{e.uploading=false;if(enrollment===e)refreshEnrollmentView();}
}
async function confirmEnrollment(id){
 const e=enrollment,proposal=e.proposals.find(p=>p.id===id),selected=e.selections[id]||[];if(busy||e.confirming||!proposal||proposal.canConfirm===false||proposal.blockedReason)return;
 const selections=proposal.candidates.filter(c=>candidateCanImport(c)&&selected.includes(candidateKey(c))).map(c=>({courseId:c.courseId,sectionId:c.sectionId}));if(!selections.length||selections.length>20)return;
 e.confirming=true;e.error='';busy=true;refreshEnrollmentView();
 try{const result=await api('/api/enrollment/confirm',{id,selections});if(enrollment!==e)return;e.receipt={...result,calendarStatus:result.calendarError||(result.calendarTask?'Calendar sync is queued. It has not completed yet.':'Saved to your student schedule. Connect Google Calendar to sync these classes.')};e.notice='Only your checked sections were imported. Resolve unmatched entries with the course picker.';await fetchEnrollmentProposals();await load(false);if(result.calendarTask?.taskId){const receipt=e.receipt;watchFeatureTask(result.calendarTask.taskId,{active:()=>enrollment===e&&e.receipt===receipt,onDone:async()=>{receipt.calendarStatus='Calendar sync completed. Check the dates in Google Calendar.';await load(false);refreshEnrollmentView();},onError:message=>{receipt.calendarStatus=`Classes are saved; calendar sync needs attention. ${message}`;refreshEnrollmentView();}});}}
 catch(error){if(enrollment===e)e.error=error.message;}
 finally{e.confirming=false;busy=false;if(enrollment===e){if(page==='academics')render();$('.enrollment-receipt')?.focus();}}
}
function reminderSettings(){return state.reminderSettings||defaultReminderSettings;}
function reminderTime(minutes){const amount=minutes%1440===0?minutes/1440:minutes%60===0?minutes/60:minutes,unit=minutes%1440===0?'day':minutes%60===0?'hour':'minute';return `${amount} ${unit}${amount===1?'':'s'}`;}
function reminderSummary(offsets){return Array.isArray(offsets)&&offsets.length?`${offsets.map(reminderTime).join(' and ')} before`:'Off';}
const reminderCategories=[['classes','Classes','A heads-up before class starts.'],['events','Campus events','Time to get to your next event.'],['deadlines','Assignments, quizzes & exams','Plan ahead for what is due.']];
const reminderPresets=[5,10,15,30,60,120,240,720,1440,2880,10080];
function reminderRow(value){return reminderPresets.includes(value)?{value:String(value)}:{value:'custom',amount:String(value%1440===0?value/1440:value%60===0?value/60:value),unit:value%1440===0?'days':value%60===0?'hours':'minutes'};}
function reminderRows(settings=reminderSettings()){return Object.fromEntries(reminderCategories.map(([key])=>[key,(settings[key]||[]).map(reminderRow)]));}
function reminderDraft(){return reminderForm.draft||(reminderForm.draft=reminderRows());}
function reminderMinutes(row){
 const factor={minutes:1,hours:60,days:1440}[row.unit];
 const value=row.value==='custom'?Number(row.amount)*factor:Number(row.value),rounded=Math.round(value);
 if((row.value==='custom'&&!String(row.amount||'').trim())||!Number.isFinite(value)||Math.abs(value-rounded)>0.000001||rounded<1||rounded>40320)throw new Error('Choose a time from 1 minute to 28 days. Custom times must equal a whole number of minutes.');
 return rounded;
}
function parseReminderFields(data){return Object.fromEntries(reminderCategories.map(([key])=>{
 const rows=data[key]||[];if(!Array.isArray(rows)||rows.length>5)throw new Error('Choose up to 5 reminder times per category.');
 return[key,[...new Set(rows.map(reminderMinutes))].sort((a,b)=>b-a)];
}));}
function reminderDraftSummary(rows){try{return reminderSummary([...new Set(rows.map(reminderMinutes))].sort((a,b)=>b-a));}catch{return 'Finish your custom time below.';}}
function reminderSelectRow(key,label,row,index){const id=`reminder-${key}-${index}`,disabled=reminderForm.saving?'disabled':'';return `<div class="reminder-row"><div class="reminder-row-main"><label class="sr-only" for="${id}-preset">${label}: reminder ${index+1}</label><select id="${id}-preset" data-reminder-field="value" data-category="${key}" data-index="${index}" ${disabled}>${reminderPresets.map(minutes=>`<option value="${minutes}" ${row.value===String(minutes)?'selected':''}>${esc(reminderTime(minutes))} before</option>`).join('')}<option value="custom" ${row.value==='custom'?'selected':''}>Custom time…</option></select><button type="button" class="reminder-remove" data-action="reminder-remove" data-category="${key}" data-index="${index}" aria-label="Remove ${esc(label.toLowerCase())} reminder ${index+1}" ${disabled}><span aria-hidden="true">×</span></button></div>${row.value==='custom'?`<div class="reminder-custom"><div><label for="${id}-amount">How long before?</label><input id="${id}-amount" data-reminder-field="amount" data-category="${key}" data-index="${index}" type="number" inputmode="decimal" step="any" value="${esc(row.amount)}" aria-describedby="reminder-custom-help reminder-settings-status" ${disabled}></div><div><label for="${id}-unit">Unit</label><select id="${id}-unit" data-reminder-field="unit" data-category="${key}" data-index="${index}" ${disabled}>${['minutes','hours','days'].map(unit=>`<option value="${unit}" ${row.unit===unit?'selected':''}>${unit[0].toUpperCase()+unit.slice(1)}</option>`).join('')}</select></div></div>`:''}</div>`;}
function remindersView(){const values=reminderForm.draft||reminderRows();return `<section id="reminder-settings" class="panel" aria-labelledby="reminder-heading"><div class="panel-head"><h2 id="reminder-heading">When should we remind you?<span class="sub">Choose a heads-up that works for your day.</span></h2><span id="reminder-draft-tag" class="tag ${reminderForm.draft?'amber':''}">${reminderForm.draft?'Unsaved changes':'Your preferences'}</span></div><div class="panel-body"><p class="reminder-intro">Pick a time before each class, event, or deadline. Add another reminder when one nudge isn’t enough.</p><form id="reminder-settings-form" novalidate><div class="reminder-fields">${reminderCategories.map(([key,label,description])=>`<fieldset class="reminder-category" ${reminderForm.saving?'disabled':''}><legend>${label}</legend><p class="reminder-category-description">${description}</p><p class="reminder-summary" id="reminders-${key}-help">${esc(reminderDraftSummary(values[key]))}</p><div class="reminder-rows">${values[key].length?values[key].map((row,i)=>reminderSelectRow(key,label,row,i)).join(''):'<p class="reminder-off">No reminders for this category.</p>'}</div><div class="reminder-category-actions">${values[key].length?`<button id="reminder-${key}-add" type="button" class="reminder-add" data-action="reminder-add" data-category="${key}" ${reminderForm.saving||values[key].length>=5?'disabled':''}>+ Add reminder</button>`:''}<button type="button" class="reminder-toggle" data-action="reminder-toggle" data-category="${key}" aria-label="Turn ${values[key].length?'off':'on'} ${label.toLowerCase()} reminders" ${reminderForm.saving?'disabled':''}>${values[key].length?'Turn off':'Turn on reminders'}</button></div>${values[key].length>=5?'<p class="form-help reminder-limit">Maximum of 5 reminders.</p>':''}</fieldset>`).join('')}</div><p class="form-help" id="reminder-custom-help">Need something different? Choose “Custom time” to set minutes, hours, or days, up to 28 days ahead.</p><div class="form-actions"><button id="save-reminders" class="button" ${reminderForm.saving?'disabled':''}>${reminderForm.saving?'Saving…':'Save reminders'}</button>${btn('Restore defaults','reset-reminder-form','secondary',`id="restore-reminder-defaults" type="button" ${reminderForm.saving?'disabled':''}`)}<button id="discard-reminder-changes" type="button" class="button quiet" data-action="discard-reminder-form" ${reminderForm.saving||!reminderForm.draft?'disabled':''}>Discard changes</button></div><div id="reminder-settings-status" role="status" aria-live="polite">${reminderForm.error?`<p class="course-error">${esc(reminderForm.error)}</p>`:''}${reminderForm.notice?`<p>${esc(reminderForm.notice)}</p>`:''}</div></form><p class="form-help reminder-delivery-note">Applies to reviewed dates with confirmed times. For Telegram delivery, turn on the matching topics in Notification choices above.</p><details class="reminder-bot-help"><summary>Calendar alerts & Telegram shortcuts</summary><p>Changes also update Google Calendar alerts after a successful sync. Export a new .ics file if you use calendar files.</p><p><code>/reminders</code> shows your settings.<br><code>/reminders classes 15m</code><br><code>/reminders deadlines 1d 2h</code><br><code>/reminders events off</code><br><code>/reminders reset</code> restores defaults.</p></details></div></section>`;}
function refreshRemindersView(focus){if(page==='connections'&&state){const element=$('#reminder-settings');if(element){element.outerHTML=remindersView();if(focus)document.getElementById(focus)?.focus();}}}
function editReminderInput(target){
 const key=target.dataset.category,index=Number(target.dataset.index),field=target.dataset.reminderField;
 if(reminderForm.saving||!reminderCategories.some(([k])=>k===key)||!Number.isInteger(index))return;
 const row=reminderDraft()[key]?.[index];if(!row||!['value','amount','unit'].includes(field))return;
 row[field]=target.value;if(field==='value'&&row.value==='custom'){row.amount??='1';row.unit??='hours';}
 reminderForm.error='';reminderForm.notice='';
 if(field==='value'||field==='unit')refreshRemindersView(field==='value'&&row.value==='custom'?`reminder-${key}-${index}-amount`:target.id);
 else {const summary=document.getElementById(`reminders-${key}-help`);if(summary)summary.textContent=reminderDraftSummary(reminderForm.draft[key]);const tag=$('#reminder-draft-tag');if(tag){tag.textContent='Unsaved changes';tag.className='tag amber';}const discard=$('#discard-reminder-changes');if(discard)discard.disabled=false;const status=$('#reminder-settings-status');if(status)status.textContent='';}
}
function editReminderAction(action,target){
 if(reminderForm.saving)return;
 const key=target.dataset.category;
 if(action==='discard-reminder-form'){reminderForm=emptyReminderForm();refreshRemindersView('save-reminders');return;}
 if(action==='reset-reminder-form'){reminderForm.draft=reminderRows(defaultReminderSettings);reminderForm.offDrafts={};reminderForm.error='';reminderForm.notice='Default times are ready. Save reminders to apply them.';refreshRemindersView('restore-reminder-defaults');return;}
 if(!reminderCategories.some(([k])=>k===key))return;
 const rows=reminderDraft()[key];let focus;
 if(action==='reminder-add'&&rows.length<5){const value=([10,15,30,60,120,240,1440,2880].find(n=>!rows.some(row=>{try{return reminderMinutes(row)===n;}catch{return false;}})))||5;rows.push(reminderRow(value));focus=`reminder-${key}-${rows.length-1}-preset`;}
 if(action==='reminder-remove'){const index=Number(target.dataset.index);if(!Number.isInteger(index)||index<0||index>=rows.length)return;rows.splice(index,1);focus=rows.length?`reminder-${key}-${Math.min(index,rows.length-1)}-preset`:null;}
 if(action==='reminder-toggle'){if(rows.length){reminderForm.offDrafts[key]=rows.map(r=>({...r}));reminderForm.draft[key]=[];}else reminderForm.draft[key]=(reminderForm.offDrafts[key]||reminderRows(defaultReminderSettings)[key]).map(r=>({...r}));}
 reminderForm.error='';reminderForm.notice='';refreshRemindersView(focus);
 if(!focus)document.querySelector(`#reminder-settings [data-action="reminder-toggle"][data-category="${key}"]`)?.focus();
}
async function saveReminderSettings(){const form=reminderForm;if(form.saving)return;const generation=++form.generation;form.error='';form.notice='';let settings;try{settings=parseReminderFields(form.draft||reminderRows());}catch(error){form.error=error.message;refreshRemindersView();$('#reminder-settings-status')?.scrollIntoView?.({block:'nearest'});return;}form.saving=true;refreshRemindersView();try{const result=await api('/api/reminders/settings',settings);if(reminderForm!==form)return;state.reminderSettings=result.settings;form.draft=null;form.offDrafts={};form.notice=result.calendarError||(result.calendarTask?'Reminders saved. Google Calendar sync is queued; it has not completed yet.':'Reminders saved. New Telegram reminders and .ics exports use these settings.');if(result.calendarTask?.taskId)watchFeatureTask(result.calendarTask.taskId,{active:()=>reminderForm===form&&form.generation===generation&&!form.draft,onDone:async()=>{await load(false);if(reminderForm!==form||form.generation!==generation||form.draft)return;form.notice='Reminders saved and Google Calendar sync completed.';refreshRemindersView();},onError:message=>{if(reminderForm!==form||form.generation!==generation||form.draft)return;form.notice=`Reminders are saved; calendar sync needs attention. ${message}`;refreshRemindersView();}});}catch(error){if(reminderForm===form)form.error=error.message;}finally{form.saving=false;if(reminderForm===form)refreshRemindersView();}}
