function refreshCoursePicker(focusId){if(page!=='academics'||!state)return;const element=$('#course-picker');if(element)element.outerHTML=coursePickerView();if(focusId)document.getElementById(focusId)?.focus();}
async function searchCourses(data){
  const p=coursePicker;if(p.loading||p.importing)return;p.term=['FA26','SP27'].includes(data.term)?data.term:'FA26';p.query=String(data.q||'').trim();p.courseId='';p.sectionId='';p.result=null;p.error='';
  if(!p.query){p.error='Enter a course code or name to search.';refreshCoursePicker('course-query');return;}
  p.loading=true;refreshCoursePicker();
  try{const result=await api(`/api/courses?term=${encodeURIComponent(p.term)}&q=${encodeURIComponent(p.query)}`);if(coursePicker===p)p.result=result;}
  catch(error){if(coursePicker===p)p.error=error.message;}
  finally{p.loading=false;if(coursePicker===p)refreshCoursePicker(p.result?.courses?.length?'course-choice':'course-query');}
}
function watchCourseCalendar(p,receipt){
  const started=Date.now(),userId=session.user.id;let checking=false;
  const timer=setInterval(async()=>{
    if(coursePicker!==p||session?.user?.id!==userId||Date.now()-started>240000){clearInterval(timer);return;}
    if(checking)return;checking=true;
    try{const tasks=await api('/api/tasks'),task=tasks.find(t=>t.id===receipt.calendarTask.taskId);if(coursePicker!==p)return;if(task?.status==='done'||task?.status==='error'){clearInterval(timer);receipt.calendarStatus=task.status==='done'?'Calendar sync completed. Check the dates in Google Calendar.':`Classes are saved; calendar sync needs attention. ${task.error||'Check Connections and retry sync.'}`;await load(false);refreshCoursePicker();}}
    catch{clearInterval(timer);if(coursePicker===p){receipt.calendarStatus='Classes are saved. Could not check calendar sync; check Connections before relying on it.';refreshCoursePicker();}}
    finally{checking=false;}
  },1500);
}
async function importCourse(){
  const p=coursePicker,course=selectedCourse(),section=selectedSection();if(busy||p.loading||p.importing||!course||!section||section.importable===false)return;
  p.importing=true;p.error='';busy=true;refreshCoursePicker();
  try{
    const result=await api('/api/courses/import',{term:p.term,courseId:course.id,sectionId:section.id});if(coursePicker!==p)return;
    p.receipt={...result,label:`${course.code} · ${section.label||section.id}`,calendarStatus:result.calendarError||(result.calendarTask?'Calendar sync is queued. Classes are saved; sync has not completed yet.':'Saved to your student schedule. Connect Google Calendar to sync these classes.')};
    await load(false);if(result.calendarTask?.taskId)watchCourseCalendar(p,p.receipt);
  }catch(error){if(coursePicker===p)p.error=error.message;}
  finally{p.importing=false;busy=false;if(coursePicker===p){if(page==='academics')render();$('.course-receipt')?.focus();}}
}
