async function runPartifulTask(url,data){
 const owner=session,ui=updatesUI,result=await api(url,data);if(session!==owner||updatesUI!==ui)return;
 if(!result.taskId){await load();toast('Partiful calendar updated.');return;}
 toast('Partiful refresh queued. Google may still have older source information.');const started=Date.now();
 const timer=setInterval(async()=>{if(session!==owner||updatesUI!==ui){clearInterval(timer);return;}try{const tasks=await api('/api/tasks');if(session!==owner||updatesUI!==ui){clearInterval(timer);return;}const task=tasks.find(item=>item.id===result.taskId);if(['done','completed','error','failed','needs_review'].includes(task?.status)){clearInterval(timer);if(['error','failed','needs_review'].includes(task.status))toast(task.error||'Partiful refresh needs attention. Check the source connection and retry.',true);else{await load();if(session===owner)toast(task.result?.calendarError||`Partiful calendar refreshed from Google.${task.result?.autoAddPending?' More events await a later import.':''}`,!!task.result?.calendarError);}}else if(Date.now()-started>240000){clearInterval(timer);toast('Partiful refresh is still processing. Check source status shortly.',true);}}catch{clearInterval(timer);if(session===owner)toast('Connection interrupted. Your queued refresh remains stored.',true);}},1500);
}
