function jobExperienceFitView(job){const fit=job.experienceFit,signals=(Array.isArray(job.stretchSignals)?job.stretchSignals:[]).filter(signal=>signal&&typeof signal.label==='string');if(!fit)return '<p class="form-help">Experience requirements have not been assessed. Check the employer’s posting.</p>';const label={'within-range':'Within counted experience',within:'Within counted experience',stretch:'Stretch opportunity','outside-range':'Beyond stretch range',beyond:'Beyond stretch range',unknown:'Experience needs checking',unconfirmed:'Experience needs checking','needs-review':'Experience needs checking',not_specified:'Years not specified'}[fit.status]||'Experience comparison';return `<div class="job-experience-fit"><span class="tag ${fit.status==='stretch'?'amber':'muted'}">${label}</span>${fit.rationale?`<p>${esc(fit.rationale)}</p>`:''}${fit.requiredExcerpt?`<details><summary>Experience requirement from posting</summary><blockquote>${esc(fit.requiredExcerpt)}</blockquote></details>`:''}${signals.length?`<details><summary>Transferable evidence to review</summary><ul>${signals.map(signal=>`<li><strong>${esc(signal.label)}</strong>${signal.evidence?`<p>${esc(signal.evidence)}</p>`:''}</li>`).join('')}</ul><p class="form-help">Resume evidence can support your application; it does not replace the employer’s requirements.</p></details>`:''}<p class="form-help">A matching suggestion, not confirmation that you meet every requirement.</p></div>`;}
