function careerCompanyInitials(company){return String(company||'?').trim().split(/\s+/).slice(0,2).map(word=>word[0]||'').join('').toUpperCase();}
function careerSaveButton(job,detail=false){const ui=careerBrowserUI;return btn(ui.saving===job.id?'Saving…':job.saved?'Saved':'Save', 'career-save-job',detail?'secondary':'quiet small',`type="button" data-id="${esc(job.id)}" aria-pressed="${job.saved===true}" aria-label="${job.saved?'Unsave':'Save'} ${esc(job.title)}" ${ui.saving?'disabled':''}`);}
function careerJobListItem(job,selected){const facts=careerJobFacts(job),posted=careerPosting(job);return `<article class="job-card career-job-row ${selected?'is-selected':''}" data-job-id="${esc(job.id)}"><button type="button" class="career-job-select" data-action="career-select-job" data-id="${esc(job.id)}" aria-pressed="${selected}" aria-controls="career-job-detail"><span class="career-company-mark" aria-hidden="true">${esc(careerCompanyInitials(job.company))}</span><span class="career-job-summary"><strong>${esc(job.title||'Role title not provided')}</strong><span class="company">${esc(job.company||'Company not provided')}</span><span class="location">${esc(job.location||'Location not published')}${facts.workplace?` · ${esc({'remote':'Remote','hybrid':'Hybrid','on-site':'On-site'}[facts.workplace]||facts.workplace)}`:''}</span>${facts.salary?`<span class="career-row-salary">${esc(facts.salary)}</span>`:''}<span class="job-posted">${posted?`<time datetime="${esc(posted.publishedAt)}">${esc(careerPostedLabel(job))}</time>`:'Posting date unavailable · not classified as recent'}</span>${careerJobUnavailable(job)?'<span class="tag muted">Closed at source</span>':job.eligible===false?'<span class="tag muted">Outside current matches</span>':facts.experience==='stretch'?'<span class="tag amber">Stretch opportunity</span>':''}</span></button><div class="career-job-row-footer"><span>${esc(job.provider?job.provider[0].toUpperCase()+job.provider.slice(1):'Employer source')}</span>${careerSaveButton(job)}</div></article>`;}
function careerJobDetail(job){
 if(!job)return `<aside id="career-job-detail" class="career-job-detail career-detail-empty"><span aria-hidden="true">↗</span><h3>Find a role worth a closer look.</h3><p>Choose a job to see the posting, experience fit, and possible introductions.</p></aside>`;
 const f=careerJobFacts(job),posted=careerPosting(job),url=applicationTrackerURL(job.applyUrl||job.url),typeNames={'full-time':'Full-time','part-time':'Part-time',internship:'Internship',contract:'Contract',temporary:'Temporary'},workplaces={remote:'Remote',hybrid:'Hybrid','on-site':'On-site'};
 return `<aside id="career-job-detail" class="career-job-detail" aria-labelledby="career-detail-heading"><div class="career-detail-back">${btn('← Back to jobs','career-job-back','quiet small','type="button"')}</div><div class="career-detail-company"><span class="career-company-mark" aria-hidden="true">${esc(careerCompanyInitials(job.company))}</span><strong>${esc(job.company||'Company not provided')}</strong></div><h3 id="career-detail-heading" tabindex="-1">${esc(job.title||'Role title not provided')}</h3><p class="career-detail-location">${esc(job.location||'Location not published')}</p><p class="career-detail-posted">${posted?`Posted ${esc(jobPostedFormat.format(new Date(posted.at)))} · New York`:'Posting date is not available from this source.'}</p><div class="career-fact-chips">${f.salary?`<span>${esc(f.salary)}</span>`:''}${f.workplace?`<span>${esc(workplaces[f.workplace]||f.workplace)}</span>`:''}${f.type?`<span>${esc(typeNames[f.type]||f.type)}</span>`:''}</div><div class="career-detail-actions">${url?`<a class="button" href="${url}" target="_blank" rel="noreferrer">Open employer posting ↗</a>`:''}${careerSaveButton(job,true)}${state.resume?btn('Prepare application','draft-job','secondary',`data-id="${esc(job.id)}" ${careerJobUnavailable(job)||careerBrowserUI.preparing?'disabled':''}`):btn('Add resume to prepare','career-tab','secondary','data-tab="profile"')}</div>${careerJobUnavailable(job)?'<p class="course-error">This role is closed at its source. Check the employer page for current opportunities.</p>':''}<p class="form-help">Prepare drafts here, then submit on the employer’s website. No application is sent by opening or saving a role.</p><section class="career-detail-section"><h4>Your experience fit</h4>${jobExperienceFitView(job)}</section>${jobWarmLeadsView(job)}<section class="career-detail-section"><h4>About this role</h4><div class="career-job-description">${esc(job.description||'A full description was not supplied by this source. Open the employer posting to review responsibilities and requirements.')}</div></section><details class="career-posting-facts"><summary>Posting details & source</summary><dl><dt>Salary</dt><dd>${esc(f.salary||'Not specified')}</dd><dt>Workplace</dt><dd>${esc(workplaces[f.workplace]||'Not specified')}</dd><dt>Employment type</dt><dd>${esc(typeNames[f.type]||'Not specified')}</dd><dt>Source</dt><dd>${esc(job.provider||'Employer source')}</dd></dl>${url?`<a href="${url}" target="_blank" rel="noreferrer">Check the original posting ↗</a>`:''}</details></aside>`;
}
function discoveredJobsView(){
 const ui=careerBrowserUI,rows=careerJobRows(),selected=rows.find(job=>job.id===ui.selectedId)||rows[0]||null;if(selected)ui.selectedId=selected.id;else{ui.selectedId='';ui.mobileDetail=false;}
 return `<section id="discovered-jobs" aria-labelledby="career-results-heading">${careerJobFilters()}<div class="career-results-heading"><div><h2 id="career-results-heading">${ui.jobTab==='saved'?'Saved jobs':'Your job matches'} <span>${rows.length}</span></h2><p>Newest source posting dates first. Unknown dates stay separate.</p></div><a href="#connections" class="career-alert-link">Manage job alerts →</a></div><div id="career-browser-status" role="status">${ui.error?`<p class="course-error">${esc(ui.error)}</p>`:''}${ui.notice?`<p class="form-help">${esc(ui.notice)}</p>`:''}</div>${rows.length?`<div class="career-browser ${ui.mobileDetail?'is-detail-open':''}"><div class="career-job-list" aria-label="Job results">${rows.slice(0,ui.visibleCount).map(job=>careerJobListItem(job,job.id===selected?.id)).join('')}${rows.length>ui.visibleCount?`<div class="career-load-more"><p>Showing ${ui.visibleCount} of ${rows.length} results</p>${btn('Show more jobs','career-more-jobs','secondary small','type="button"')}</div>`:''}</div>${careerJobDetail(selected)}</div>`:`<div class="career-no-results"><span aria-hidden="true">↗</span><h3>${ui.jobTab==='saved'?(state.jobs.some(job=>job.saved)?'No saved jobs match these filters.':'Keep your shortlist here.'):state.jobs.length?'No roles match these filters.':'Start with the work you want to do.'}</h3><p>${ui.jobTab==='saved'?(state.jobs.some(job=>job.saved)?'Clear your filters to see all bookmarked roles, including older postings.':'Save a role from Find jobs to return to it later. Saving is private to your account.'):state.jobs.length?'Try All dates or Unknown date, or clear your filters. Missing posting dates are never treated as new.':'Enter a title and location above, or upload a resume to search from your experience. No sample openings are presented as live jobs.'}</p>${btn(ui.jobTab==='saved'&&!state.jobs.some(job=>job.saved)?'Browse jobs':'Clear filters',ui.jobTab==='saved'&&!state.jobs.some(job=>job.saved)?'career-tab':'career-clear-filters','secondary',ui.jobTab==='saved'&&!state.jobs.some(job=>job.saved)?'data-tab="find"':'')}</div>`}</section>`;
}
function refreshCareerWorkspace(focusId){if(page!=='careers'||!state)return;const element=$('#career-workspace');if(element)element.outerHTML=careerWorkspaceView();if(focusId)document.getElementById(focusId)?.focus();}
function setCareerTab(tab,{focus=false}={}){if(!['find','saved','applications','profile'].includes(tab))return;captureJobSearch();captureCareerQuestion();const ui=careerBrowserUI;ui.tab=tab;ui.mobileDetail=false;ui.visibleCount=40;ui.selectedId='';if(tab==='find'||tab==='saved'){ui.jobTab=tab;jobRecency=ui.recencies[tab];}refreshCareerWorkspace(focus?'career-tab-'+tab:undefined);if(tab==='profile')loadDemographics();}
function updateCareerFilter(field,value){if(!Object.hasOwn(careerBrowserUI.filters,field))return;careerBrowserUI.filters[field]=String(value||'');careerBrowserUI.mobileDetail=false;careerBrowserUI.visibleCount=40;careerBrowserUI.selectedId='';const element=$('#discovered-jobs');if(element)element.outerHTML=discoveredJobsView();}
async function saveCareerJob(id){const ui=careerBrowserUI,owner=session,job=state.jobs.find(item=>item.id===id);if(!owner?.user||!job||ui.saving)return;ui.saving=id;ui.error='';ui.notice='';refreshCareerWorkspace();try{const result=await api('/api/jobs/save',{id,saved:job.saved!==true});if(session!==owner||careerBrowserUI!==ui)return;if(typeof result.saved!=='boolean')throw new Error('Could not confirm this saved-job change. Refresh and try again.');const current=state.jobs.find(item=>item.id===id);if(current){current.saved=result.saved;current.savedAt=result.savedAt||null;}ui.notice=result.saved?'Saved to your shortlist.':'Removed from your saved jobs.';}catch(error){if(session===owner&&careerBrowserUI===ui)ui.error=error.message;}finally{if(session===owner&&careerBrowserUI===ui){ui.saving='';refreshCareerWorkspace();}}}

async function prepareCareerApplication(id){const ui=careerBrowserUI,owner=session,job=state.jobs.find(item=>item.id===id);if(!owner?.user||!job||careerJobUnavailable(job)||ui.preparing)return;if(!state.resume){setCareerTab('profile',{focus:true});return;}captureCareerQuestion();ui.preparing=id;ui.tab='applications';ui.mobileDetail=false;ui.workbenchOpen=true;ui.applicationError='';ui.applicationNotice=`Preparing a draft for ${job.title}. Nothing is sent to the employer.`;refreshCareerWorkspace('career-application-status');const active=()=>session===owner&&careerBrowserUI===ui&&ui.preparing===id;try{const result=await api('/api/jobs/draft',{id});if(!active())return;if(!result.taskId)throw new Error('Application preparation was not queued. Please try again.');watchFeatureTask(result.taskId,{active,onDone:async()=>{await load(false);if(!active())return;ui.preparing='';ui.applicationNotice='Your application draft is ready below. Review its facts and answers before using the employer’s form.';ui.workbenchOpen=true;refreshCareerWorkspace(ui.tab==='applications'?'career-application-status':undefined);},onError:message=>{if(active()){ui.preparing='';ui.applicationNotice='';ui.applicationError=message;refreshCareerWorkspace();}}});}catch(error){if(active()){ui.preparing='';ui.applicationNotice='';ui.applicationError=error.message;refreshCareerWorkspace();}}}

async function saveCareerWorkbench(id,data){const ui=careerBrowserUI,owner=session;if(ui.applicationSaving||!owner?.user||!state.applications.some(application=>application.id===id))return;const draft=ui.applicationEdits[id];ui.applicationSaving=id;ui.applicationError='';refreshCareerWorkspace();try{await api('/api/applications/review',{id,whyCompany:data.whyCompany,relevantExperience:data.relevantExperience});if(session!==owner||careerBrowserUI!==ui)return;if(ui.applicationEdits[id]===draft)delete ui.applicationEdits[id];await load(false);if(session!==owner||careerBrowserUI!==ui)return;ui.applicationNotice='Your application answers are saved as reviewed. No employer has received them.';}catch(error){if(session===owner&&careerBrowserUI===ui)ui.applicationError=error.message;}finally{if(session===owner&&careerBrowserUI===ui){ui.applicationSaving='';refreshCareerWorkspace();}}}

function refreshLinkedIn(){if(page!=='careers'||!state)return;const panel=$('#linkedin-connections');if(panel)panel.outerHTML=linkedinView();const jobs=$('#discovered-jobs');if(jobs)jobs.outerHTML=discoveredJobsView();}
async function readLinkedInCSV(file){if(!file)return;const ui=linkedInUI,owner=session;if(ui.pending||ui.reading)return;ui.error='';ui.notice='';ui.csv='';ui.name='';if(!/\.csv$/i.test(file.name)||file.size>linkedInCSVLimit){ui.error='Choose a CSV file no larger than 8 MB.';refreshLinkedIn();return;}ui.reading=true;const version=state.linkedinConnections?.version||null;refreshLinkedIn();try{const csv=await file.text();if(linkedInUI!==ui||session!==owner)return;if(!csv.trim()||csv.length>linkedInCSVLimit)throw new Error('The CSV is empty or exceeds the 8 MB limit.');ui.csv=csv;ui.name=file.name;ui.expectedVersion=version;ui.reading=false;ui.notice='CSV loaded in this page. Select Import connections when you are ready.';refreshLinkedIn();}catch(error){if(linkedInUI===ui&&session===owner){ui.reading=false;ui.error=error.message;refreshLinkedIn();}}}
async function linkedinRequest(kind){const ui=linkedInUI,owner=session;if(ui.pending||ui.reading||!owner?.user)return;let payload={};if(kind==='import'){if(!ui.csv)return;payload={csv:ui.csv,name:ui.name,expectedVersion:ui.expectedVersion};}else if(kind==='settings'){const value=$('#linkedin-refresh-days')?.value;payload={refreshDays:value==='off'?null:Number(value)};if(![null,7,14,30,90].includes(payload.refreshDays)){ui.error='Choose off, biweekly, monthly, or quarterly.';refreshLinkedIn();return;}}ui.pending=kind;ui.error='';ui.notice='';ui.matches={};refreshLinkedIn();const active=()=>linkedInUI===ui&&session===owner;try{const result=await api(`/api/career/linkedin/${kind}`,payload);if(!active())return;await load(false);if(!active())return;ui.pending='';ui.reminderDraft=undefined;if(kind==='import'||kind==='delete'){ui.csv='';ui.name='';ui.expectedVersion=null;}ui.notice=result.notice||(kind==='delete'?'Imported connections and refresh reminders removed.':kind==='settings'?'Export refresh reminder saved.':'Connections imported privately. Check a saved job for possible employer matches.');refreshLinkedIn();}catch(error){if(active()){ui.pending='';ui.error=error.message;refreshLinkedIn();}}}
async function findLinkedInMatches(id){const ui=linkedInUI,owner=session,metadata=state.linkedinConnections||{};if(ui.pending||ui.reading||!metadata.connected||!state.jobs.some(job=>job.id===id)||ui.matches[id]?.pending)return;const entry={pending:true,error:'',result:null,version:metadata.version||null};ui.matches[id]=entry;refreshLinkedIn();const active=()=>linkedInUI===ui&&session===owner&&ui.matches[id]===entry;try{const result=await api('/api/career/linkedin/matches?jobId='+encodeURIComponent(id));if(!active())return;if((state.linkedinConnections?.version||null)!==entry.version||(result.version||null)!==entry.version)throw new Error('Your imported connections changed. Refresh this page before checking again.');entry.pending=false;entry.result=result;refreshLinkedIn();}catch(error){if(active()){entry.pending=false;entry.error=error.message;refreshLinkedIn();}}}

function careerDiscoveryView(){return `<div id="career-discovery">${jobSearchView()}${discoveredJobsView()}${careerSourcesView()}</div>`;}
function refreshCareerDiscovery(focusId){refreshCareerWorkspace(focusId);}
function captureJobSearch(){const form=$('#job-search');if(form)jobSearchUI.draft={jobTitles:form.querySelector('[name="jobTitles"]').value,jobLocation:form.querySelector('[name="jobLocation"]').value,stretchYears:Number(form.querySelector('[name="stretchYears"]').value)};}
function captureExperience(){const form=$('#career-experience-form');if(!form)return;experienceUI.sourceHash=form.dataset.sourceHash;experienceUI.draft=[...form.querySelectorAll('[data-experience-role]')].map(row=>({id:row.dataset.experienceRole,employmentType:row.querySelector('[data-experience-field="employmentType"]').value,startMonth:row.querySelector('[data-experience-field="startMonth"]').value||null,endMonth:notificationChecked(row.querySelector('[data-experience-field="ongoing"]'))?'present':row.querySelector('[data-experience-field="endMonth"]').value||null}));}
function watchJobSearch(ids,ui,owner){const pending=new Set(ids),start=Date.now();let checking=false;const active=()=>jobSearchUI===ui&&session===owner;const timer=setInterval(async()=>{if(!active()){clearInterval(timer);return;}if(Date.now()-start>240000){clearInterval(timer);ui.pending=false;ui.notice='Search is still queued. Check source coverage and refresh later; work may continue in the background.';refreshCareerDiscovery();return;}if(checking)return;checking=true;try{const tasks=await api('/api/tasks');if(!active())return;const rows=tasks.filter(task=>pending.has(task.id));if(rows.length===pending.size&&rows.every(task=>['done','error','needs_review'].includes(task.status))){clearInterval(timer);await load(false);if(!active())return;ui.pending=false;const failed=rows.filter(task=>task.status!=='done').length;ui.notice=failed?`Search completed with ${failed} source ${failed===1?'task':'tasks'} needing attention. Review coverage below.`:'Queued employer searches completed. Review matches, warnings, and source coverage below.';refreshCareerDiscovery();}}catch(error){clearInterval(timer);if(active()){ui.pending=false;ui.error=error.message;refreshCareerDiscovery();}}finally{checking=false;}},1500);}
async function searchJobs({saveOnly=false,advanced=null}={}){const ui=jobSearchUI,owner=session;if(ui.pending||!owner?.user)return;captureJobSearch();const d=ui.draft||jobSearchDraft();ui.error='';ui.notice='';ui.warnings=[];if(!advanced&&!String(d.jobTitles).trim()&&!state.resume){ui.error='Add target job titles or upload a resume before searching.';refreshCareerDiscovery();return;}if(!advanced&&![2,3].includes(Number(d.stretchYears))){ui.error='Choose a stretch range of two or three years.';refreshCareerDiscovery();return;}ui.pending=true;refreshCareerDiscovery();const active=()=>jobSearchUI===ui&&session===owner;try{if(!advanced){await api('/api/settings',{jobTitles:String(d.jobTitles).trim(),jobLocation:String(d.jobLocation).trim()});if(!active())return;await api('/api/jobs/discovery/settings',{stretchYears:Number(d.stretchYears)});if(!active())return;}if(saveOnly){await load(false);if(!active())return;ui.pending=false;ui.draft=null;ui.notice='Search preferences saved.';refreshCareerDiscovery();return;}const result=await api('/api/jobs/search',advanced||{});if(!active())return;ui.warnings=Array.isArray(result.warnings)?result.warnings.filter(value=>typeof value==='string').slice(0,20):[];const ids=[...new Set([...(result.taskIds||[]),result.taskId,result.experienceTaskId].filter(Boolean))];await load(false);if(!active())return;ui.notice=ids.length?'Employer searches are queued. Matching roles will appear below as the sources finish.'+(result.experienceTaskId?' Experience analysis is also pending; experience comparisons stay tentative until it is ready.':''):'Source settings saved. Check coverage below.';if(ids.length)watchJobSearch(ids,ui,owner);else ui.pending=false;refreshCareerDiscovery();}catch(error){if(active()){ui.pending=false;ui.error=error.message;refreshCareerDiscovery();}}}
async function analyzeExperience(){const ui=experienceUI,owner=session;if(ui.pending||!state.resume)return;ui.pending='analyzing';ui.error='';ui.notice='Resume experience analysis is queued. Check each role and date when it is ready.';refreshCareerDiscovery();const active=()=>experienceUI===ui&&session===owner;try{const result=await api('/api/career/experience/analyze',{});if(!active())return;watchFeatureTask(result.taskId,{active,onDone:async()=>{await load(false);if(!active())return;ui.pending='';ui.draft=null;ui.sourceHash='';ui.notice='Experience analysis is ready. Confirm any uncertain work types and dates below.';refreshCareerDiscovery();},onError:message=>{if(active()){ui.pending='';ui.error=message;ui.notice='';refreshCareerDiscovery();}}});}catch(error){if(active()){ui.pending='';ui.error=error.message;refreshCareerDiscovery();}}}
async function saveExperience(){const ui=experienceUI,owner=session;if(ui.pending||!state.careerExperience?.sourceHash||state.careerExperience.stale)return;captureExperience();const payload={sourceHash:ui.sourceHash,roles:ui.draft.map(role=>({id:role.id,employmentType:role.employmentType,startMonth:role.startMonth||null,endMonth:role.endMonth||null}))};ui.pending='saving';ui.error='';ui.notice='';refreshCareerDiscovery();const active=()=>experienceUI===ui&&session===owner;try{await api('/api/career/experience',payload);if(!active())return;await load(false);if(!active())return;ui.pending='';ui.draft=null;ui.sourceHash='';ui.notice='Experience choices saved. Overlapping full-time months count once; unresolved roles remain unconfirmed.';refreshCareerDiscovery();}catch(error){if(active()){ui.pending='';ui.error=error.message;refreshCareerDiscovery();}}}

function careerWorkbenchView(){return `<details id="career-workbench" class="career-workbench" ${careerBrowserUI.workbenchOpen?'open':''}><summary>Application drafts & local demo</summary><div class="career-workbench-body"><div class="source-heading">APPLICATION WORKBENCH</div><div class="notice">Live employer submission is not implemented in this version. You can prepare answers, open the employer’s form, and demonstrate a real submission to the local sandbox. Sandbox receipts are clearly labeled.</div>${state.applications.map(a=>`<article class="application"><h3>${esc(a.title)}</h3><p class="subtitle">${esc(a.company)}</p><span class="tag ${a.status==='sandbox-submitted'?'amber':'green'}">${esc(a.status)}</span><form class="application-form" data-id="${esc(a.id)}"><div class="field"><label>Why this company?<textarea name="whyCompany" rows="5" required ${careerBrowserUI.applicationSaving?'disabled':''}>${esc(careerBrowserUI.applicationEdits[a.id]?.whyCompany??a.answers.whyCompany)}</textarea></label></div><div class="field"><label>Relevant experience<textarea name="relevantExperience" rows="5" required ${careerBrowserUI.applicationSaving?'disabled':''}>${esc(careerBrowserUI.applicationEdits[a.id]?.relevantExperience??a.answers.relevantExperience)}</textarea></label></div><p class="form-help">Qualification gaps: ${esc((a.answers.gaps||[]).join(' · ')||'Review against employer requirements.')}<br>Still needs your input: ${esc((a.answers.unanswered||[]).join(' · '))}</p><div class="form-actions"><button class="button secondary" ${careerBrowserUI.applicationSaving?'disabled':''}>${careerBrowserUI.applicationSaving===a.id?'Saving…':'Save reviewed answers'}</button>${a.status==='reviewed'?btn('Submit to LOCAL sandbox','sandbox-submit','',`data-id="${esc(a.id)}" ${careerBrowserUI.applicationEdits[a.id]||careerBrowserUI.applicationSaving?'disabled':''}`):''}${a.receipt?`<code>${esc(a.receipt)}</code><span class="tag amber">No employer received this</span>`:''}</div></form></article>`).join('')}</div></details>`;}
function careerWorkspaceView(){const ui=careerBrowserUI,tabs=[['find','Find jobs'],['saved','Saved'],['applications','Applications'],['profile','Resume & profile']],saved=state.jobs.filter(job=>job.saved===true).length;return `<div id="career-workspace"><nav id="career-tabs" class="career-tabs" role="tablist" aria-label="Career workspace">${tabs.map(([id,label])=>`<button type="button" id="career-tab-${id}" role="tab" data-action="career-tab" data-tab="${id}" aria-selected="${ui.tab===id}" aria-controls="career-panel-${['find','saved'].includes(id)?'jobs':id}" tabindex="${ui.tab===id?'0':'-1'}">${label}${id==='saved'&&saved?`<span>${saved}</span>`:id==='applications'&&state.applicationTracker?.length?`<span>${state.applicationTracker.length}</span>`:''}</button>`).join('')}</nav><section id="career-panel-jobs" class="career-tab-panel" role="tabpanel" aria-labelledby="career-tab-${ui.jobTab}" ${['find','saved'].includes(ui.tab)?'':'hidden'}>${careerDiscoveryView()}</section><section id="career-panel-applications" class="career-tab-panel" role="tabpanel" aria-labelledby="career-tab-applications" ${ui.tab==='applications'?'':'hidden'}>${applicationTrackerView()}<div id="career-application-status" role="status" tabindex="-1">${ui.applicationNotice?`<p>${esc(ui.applicationNotice)}</p>`:''}${ui.applicationError?`<p class="course-error">${esc(ui.applicationError)}</p>`:''}</div><details id="career-answer-tools" class="career-answer-tools" ${ui.answersOpen?'open':''}><summary>Prepare answers for an application</summary><div>${careerQuestionView()}${careerAnswersView()}</div></details>${careerWorkbenchView()}</section><section id="career-panel-profile" class="career-tab-panel" role="tabpanel" aria-labelledby="career-tab-profile" ${ui.tab==='profile'?'':'hidden'}><div class="career-resume-status"><div><strong>${state.resume?esc(state.resume.name):'Bring your experience into focus.'}</strong><p>${state.resume?'Your resume supports job matching and grounded application drafts.':'Upload your resume to get writing suggestions, review your experience, and prepare application answers.'}</p></div>${btn(state.resume?'Replace resume':'Upload resume','upload-resume','secondary')}</div>${careerToolsView()}</section></div>`;}
function careers(){return `<header class="career-page-heading"><div><h1>Career studio</h1><p>Find your next role. Make the most of your experience.</p></div><div class="career-heading-actions">${state.resume?'<span class="tag green">Resume ready</span>':btn('Upload resume','upload-resume','secondary small')}</div></header><div id="career-tools">${careerWorkspaceView()}</div>`;}

const notificationTopics=[['school','School','Classes, deadlines, and Product Studio'],['events','Events','Campus and social plans'],['jobs','Jobs','Matching roles from your sources'],['news','News','Selected newsletter briefings'],['games','Games','Coming soon · preference only']];
function currentNotifications(){const raw=state.notifications||{},topics=Object.fromEntries(notificationTopics.map(([key])=>[key,['off','daily','alerts','both'].includes(raw.topics?.[key])?raw.topics[key]:'off']));return{enabled:raw.enabled===true,topics};}
function notificationChecked(el){return typeof el?.checked==='boolean'?el.checked:!!el?.hasAttribute('checked');}
function readNotificationForm(form){return{enabled:notificationChecked(form.querySelector('#notifications-enabled')),topics:Object.fromEntries(notificationTopics.map(([key])=>{const daily=notificationChecked(form.querySelector(`#notification-${key}-daily`)),alerts=notificationChecked(form.querySelector(`#notification-${key}-alerts`));return[key,daily&&alerts?'both':daily?'daily':alerts?'alerts':'off'];}))};}
function notificationsView(){const ui=notificationsUI,settings=ui.draft||currentNotifications(),enabledDaily=notificationTopics.some(([key])=>['daily','both'].includes(settings.topics[key])),any=notificationTopics.some(([key])=>settings.topics[key]!=='off');return `<section id="notification-settings" class="panel" aria-labelledby="notifications-heading"><div class="panel-head"><h2 id="notifications-heading">Choose what reaches you<span class="sub">Your topics. Your pace.</span></h2><span class="tag">PRIVATE TELEGRAM</span></div><div class="panel-body"><p>Choose what goes in your morning briefing and what may send an additional alert. These choices control automatic messages; direct requests to your assistant still receive replies.</p><form id="notification-settings-form"><div class="notification-master"><label class="checkbox-control" for="notifications-enabled"><input id="notifications-enabled" name="enabled" type="checkbox" ${settings.enabled?'checked':''} ${ui.saving?'disabled':''}><span>Allow proactive Telegram messages</span></label></div><table class="notification-table"><caption class="sr-only">Notification topics and delivery choices</caption><thead><tr><th scope="col">Topic</th><th scope="col">Morning<br>briefing</th><th scope="col">Additional<br>alerts</th></tr></thead><tbody>${notificationTopics.map(([key,label,help])=>`<tr><th scope="row"><strong>${label}</strong><small>${help}</small></th>${[['daily','morning briefing'],['alerts','additional alerts']].map(([mode,description])=>`<td><label class="checkbox-control" for="notification-${key}-${mode}"><input id="notification-${key}-${mode}" name="${key}-${mode}" type="checkbox" ${settings.topics[key]===mode||settings.topics[key]==='both'?'checked':''} ${ui.saving?'disabled':''} aria-label="${label}: ${description}" ${key==='games'?'aria-describedby="notification-games-help"':''}><span class="sr-only">${label}: ${description}</span></label></td>`).join('')}</tr>`).join('')}</tbody></table><p id="notification-games-help" class="form-help">Games are not available yet. Your preference is saved for when they are available; it does not enable any game or game messages now.</p><div id="notification-draft-help" class="form-help">${!settings.enabled?'Proactive delivery is off. Your topic choices stay saved until you enable it.':!any?'All topics are off. Choose the updates you want, then save.':enabledDaily&&state.dailyBriefing?.enabled===false?'Morning briefing scheduling is off. Enable it above for daily delivery.':'Morning topics use the briefing time above. Additional alerts use your reminder and source settings.'}</div><div class="form-actions"><button class="button" ${ui.saving?'disabled':''}>${ui.saving?'Saving…':'Save notification choices'}</button>${btn('Discard unsaved changes','reset-notifications','quiet',ui.saving||!ui.draft?'disabled':'')}</div><div id="notification-settings-status" role="status">${ui.draft&&!ui.saving?'<p class="form-help">Unsaved notification choices.</p>':''}${ui.error?`<p class="course-error">${esc(ui.error)}</p>`:''}${ui.notice?`<p>${esc(ui.notice)}</p>`:''}</div></form><p class="form-help">New students start with all topics off. Existing students keep their prior school, event, and job delivery choices. Linking Telegram and keeping the host online are still required. Pausing reminders also pauses automatic delivery.</p></div></section>`;}
function refreshNotifications(focusId){if(page!=='connections'||!state)return;const element=$('#notification-settings');if(element)element.outerHTML=notificationsView();if(focusId)document.getElementById(focusId)?.focus();}
async function saveNotifications(form){const ui=notificationsUI,owner=session;if(ui.saving||!owner?.user)return;ui.draft=readNotificationForm(form);const payload={enabled:ui.draft.enabled,topics:{...ui.draft.topics}};ui.saving=true;ui.error='';ui.notice='';refreshNotifications();try{await api('/api/notifications/settings',payload);if(session!==owner||notificationsUI!==ui)return;await load(false);if(session!==owner||notificationsUI!==ui)return;ui.saving=false;ui.draft=null;ui.notice='Notification choices saved.';refreshNotifications();}catch(error){if(session===owner&&notificationsUI===ui){ui.saving=false;ui.error=error.message;refreshNotifications();}}}
const newsProviders=[{id:'wsj10point',name:'WSJ · The 10-Point',short:'WSJ',description:'Your imported Wall Street Journal briefing'},{id:'dailypitch',name:'PitchBook · Daily Pitch',short:'PB',description:'Your imported private-market briefing'}];
function newsArticleURL(value,provider){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.port)return '';if(provider==='wsj10point'&&['wsj.com','www.wsj.com'].includes(u.hostname)&&u.pathname.split('/').filter(Boolean).length>=2&&!/^\/(account|login|subscribe|newsletters|preference-center)(?:\/|$)/i.test(u.pathname))return esc('https://www.wsj.com'+u.pathname);if(provider==='dailypitch'&&['pitchbook.com','www.pitchbook.com'].includes(u.hostname)&&/^\/news\/(articles|reports)\/[^/]+/.test(u.pathname))return esc('https://pitchbook.com'+u.pathname);return '';}catch{return '';}}
function newsDate(value){const parsed=/^\d{4}-\d{2}-\d{2}$/.test(String(value))?`${value}T12:00:00Z`:value;return Number.isFinite(Date.parse(parsed))?new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',year:'numeric'}).format(new Date(parsed)):'Date not provided';}
function newsDeliveryLabel(){const p=currentNotifications();return state.profile.paused?'Paused':!p.enabled?'Proactive messages off':({off:'Off',daily:'Morning briefing',alerts:'Additional alerts',both:'Morning briefing and additional alerts'}[p.topics.news]||'Off');}
function newsMonitoringStatus(news){const mailbox=news.mailbox||{};if(state.profile.paused)return 'Paused with your assistant';if(!mailbox.connected)return 'Email not connected';if(mailbox.lastError)return 'Needs attention';if(!news.settings?.sources?.length)return 'Choose newsletters';if(mailbox.continuous&&(mailbox.automatic||mailbox.mode==='automatic'))return 'Automatic reading on';if(mailbox.continuous&&mailbox.labelId)return 'Reading a selected label';return 'Reading is off';}
function newsSummaryCard(provider,news){
 const info=(news.providers||[]).find(row=>row.id===provider.id),latest=info?.latest||(news.summaries||[]).find(row=>row.provider===provider.id),stamp=latest?.receivedAt||latest?.date,age=Date.parse(state.now)-Date.parse(stamp),freshnessState=info?.freshness||(!latest?'missing':!Number.isFinite(age)||age< -86400000?'unknown':age>48*60*60*1000?'stale':'fresh'),freshness=({missing:'No briefing yet',unknown:'Date uncertain',stale:'Older briefing',fresh:'Latest edition'}[freshnessState]||'Date uncertain');
 const scan=news.mailbox?.lastScan,missing=(news.settings?.sources||[]).includes(provider.id)&&scan?.missingSources?.includes(provider.id),emptyText=missing?`No matching ${provider.id==='wsj10point'?'The 10-Point':'Daily Pitch'} email was found in the recent search${scan.truncated?' (search was limited)':''}. Check that this newsletter reaches your connected inbox.`:'Choose this newsletter and select Find my newsletters to read recent editions from your inbox.';
 return `<article class="panel news-card news-${provider.id}" aria-labelledby="news-${provider.id}-heading"><div class="panel-head"><div class="news-provider-heading"><span class="news-monogram" aria-hidden="true">${provider.short}</span><h2 id="news-${provider.id}-heading">${provider.name}</h2></div><span class="tag ${latest&&['stale','unknown'].includes(freshnessState)?'amber':''}">${freshness}</span></div><div class="panel-body">${latest?`<div class="news-edition"><strong>${esc(latest.subject||latest.name||'Newsletter briefing')}</strong><p class="form-help">${esc(newsDate(latest.date))} · A quick read</p></div><ul class="news-bullets">${(latest.bullets||[]).slice(0,3).map(bullet=>{const url=newsArticleURL(bullet.url,provider.id);return `<li><p>${esc(bullet.text)}</p>${url?`<a href="${url}" target="_blank" rel="noreferrer">Read at ${provider.id==='wsj10point'?'WSJ':'PitchBook'} ↗</a>`:''}</li>`;}).join('')}</ul>${!latest.bullets?.length?'<p>No summary points were returned for this edition.</p>':''}<details class="news-source-notes"><summary>About this summary</summary><p class="form-help">${latest.source?.kind==='gmail'?(latest.source.senderDomainMatched?'Sender domain metadata matched the selected publisher. This is not an authenticity guarantee.':'The sender domain was not matched to the selected publisher. Check your original email.'):'Manually imported content; the publisher and sender have not been independently verified.'}</p>${latest.warnings?.length?`<ul class="course-warnings">${latest.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}<p class="form-help">A saved newsletter summary, not a live news feed. Read the original reporting for context. Article access may require your own publisher subscription. Saved ${esc(newsDate(latest.createdAt))}.</p></details>`:`<div class="news-empty"><p>${esc(emptyText)}</p><a class="news-subscribe" href="${provider.id==='dailypitch'?'https://pitchbook.com/subscribe':'https://www.wsj.com/10PointNL'}" target="_blank" rel="noreferrer">${provider.id==='dailypitch'?'Subscribe to Daily Pitch':'Subscribe to The 10-Point'} ↗</a></div>`}</div></article>`;
}
function newsPage(){
 const ui=newsUI,news=state.news||{},mailbox=news.mailbox||{},selected=ui.sourceDraft||news.settings?.sources||[],savedSources=news.settings?.sources||[],paused=!!state.profile.paused,reading=mailbox.continuous&&mailbox.connected,scan=mailbox.lastScan,hasSummaries=newsProviders.some(provider=>(news.providers||[]).find(info=>info.id===provider.id)?.latest||(news.summaries||[]).some(summary=>summary.provider===provider.id)),cardsHTML=`<div class="news-grid">${newsProviders.map(provider=>newsSummaryCard(provider,news)).join('')}</div>`;
 return heading('YOUR READING, A LITTLE LIGHTER.','A moment to catch up.','The 10-Point and Daily Pitch, summarized from your own email.')+`<section id="news-workspace"><div class="news-top-note"><span class="tag">PRIVATE TO YOU</span><p>Automatic News delivery: <strong>${newsDeliveryLabel()}</strong>. <a href="#connections">Choose Telegram delivery</a>.</p></div><div class="news-status" role="status" aria-live="polite">${ui.pending?'<p>Finding and summarizing your selected newsletters…</p>':''}${ui.error?`<p class="course-error">${esc(ui.error)}</p>`:''}${ui.notice?`<p>${esc(ui.notice)}</p>`:''}</div>${hasSummaries?cardsHTML:''}
 <section id="news-source-settings" class="panel news-automatic"><div class="panel-head"><div><h2>Find my newsletters</h2><p class="form-help">Choose your publications. BRB finds their recent emails and makes a short briefing.</p></div><span class="tag ${mailbox.lastError?'amber':''}">${esc(newsMonitoringStatus(news))}</span></div><div class="panel-body"><form id="news-source-form"><fieldset class="news-source-choices" ${ui.pending||!mailbox.connected||paused?'disabled':''}><legend>Newsletters to read</legend>${newsProviders.map(provider=>`<label class="checkbox-control" for="news-source-${provider.id}"><input id="news-source-${provider.id}" name="${provider.id}" type="checkbox" ${selected.includes(provider.id)?'checked':''}><span>${provider.name}</span></label>`).join('')}</fieldset><div class="form-actions">${mailbox.connected?`<button class="button" ${ui.pending||paused||!selected.length?'disabled':''}>${ui.pending?'Finding newsletters…':'Find my newsletters'}</button>`:btn('Connect Google email','connect-news','',ui.pending?'disabled':'')}${reading?btn('Pause email reading','disconnect-news','quiet',ui.pending?'disabled':''):''}</div>${!mailbox.connected?'<p class="form-help">Connect the Google inbox receiving your newsletters, then choose what to read.</p>':`<p class="form-help">Using <strong>${esc(mailbox.accountEmail||'your connected Google inbox')}</strong>. Searches recent publisher emails; no Gmail label needed.</p>`}${paused?'<p class="form-help">Your assistant is paused. <a href="#connections">Resume it in Connections</a> before reading email.</p>':''}${ui.sourceDraft?'<p class="form-help">Your choices take effect when you select Find my newsletters.</p>':''}</form>${mailbox.lastError?`<p class="course-error">${esc(mailbox.lastError)}</p>`:''}${savedSources.length&&scan?.matched===0?`<p class="news-search-result">No matching newsletters found in this recent search${scan.truncated?' (search was limited)':''}. Check your subscriptions and connected inbox, then try again.</p>`:''}${mailbox.lastSuccess?`<p class="form-help">Last checked ${esc(newsDate(mailbox.lastSuccess))}. ${reading?'New editions are checked while BRB is online.':'Email reading is paused; saved briefings stay here.'}</p>`:''}<p class="news-consent-note">Google grants mailbox-wide read-only access. BRB searches the newsletters you choose. Starting email reading does not enable Telegram delivery.</p></div></section>${hasSummaries?'':cardsHTML}
 <details id="news-advanced" class="news-advanced" ${ui.advancedOpen?'open':''}><summary>More ways to bring news in <span>Use a Gmail label, paste a newsletter, or review privacy details</span></summary><div class="news-advanced-body"><section id="news-label-settings" class="panel"><div class="panel-head"><h2>Use a Gmail label instead<span class="sub">Optional: limit BRB’s search to a label you maintain</span></h2></div><div class="panel-body"><p class="form-help">Choose a separate custom label for newsletters. Google’s permission remains mailbox-wide; BRB applies your label as a search rule.</p><div class="form-actions">${btn(mailbox.connected?'Reconnect shared mailbox':'Connect Google email reading','connect-news','secondary',ui.pending?'disabled':'')}${mailbox.connected?btn('Choose news label','list-news-labels','secondary',ui.pending?'disabled':'')+btn('Check news label','sync-news','quiet',ui.pending||!mailbox.labelId||!mailbox.continuous||!savedSources.length||paused?'disabled':''):''}${btn('Save publisher choices only','save-news-sources','quiet',ui.pending?'disabled':'')}</div>${ui.labels.length?`<form id="news-label-form"><div class="field"><label for="news-label">Custom Gmail label for newsletters</label><select id="news-label" name="labelId" required ${ui.pending?'disabled':''}><option value="">Choose the news label</option>${ui.labels.map(label=>`<option value="${esc(label.id)}">${esc(label.name)}</option>`).join('')}</select></div><button class="button secondary" ${ui.pending||!savedSources.length?'disabled':''}>Use this news label</button>${!savedSources.length?'<p class="form-help">Save at least one publisher choice before enabling label monitoring.</p>':''}</form>`:''}<p class="form-help">${mailbox.labelId?`Selected label: ${esc(mailbox.labelName||'News label')}. Choosing it switches automatic publisher search to label reading.`:'No news label selected; automatic publisher search works without one.'} Reconnecting a shared mailbox may require choosing event and news settings again.</p></div></section>
<section id="news-import" class="panel"><div class="panel-head"><h2>Bring a newsletter<span class="sub">Paste text or import an exported email</span></h2><span class="tag">EXPLICIT IMPORT</span></div><div class="panel-body"><form id="news-import-form"><div class="form-grid"><div class="field"><label for="news-import-provider">Newsletter</label><select id="news-import-provider" name="provider" ${ui.pending?'disabled':''}>${newsProviders.map(p=>`<option value="${p.id}" ${ui.draft.provider===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="field"><label for="news-import-name">Import name · optional</label><input id="news-import-name" name="name" maxlength="160" value="${esc(ui.draft.name)}" placeholder="Tuesday’s newsletter" ${ui.pending?'disabled':''}></div><div class="field"><label for="news-import-format">Pasted content</label><select id="news-import-format" name="format" ${ui.pending?'disabled':''}><option value="text" ${ui.draft.format==='text'?'selected':''}>Newsletter text</option><option value="eml" ${ui.draft.format==='eml'?'selected':''}>Exported email (.eml text)</option></select></div><div class="field news-eml-field"><label for="news-eml-file">Or choose an .eml file · max 100 KB</label><input id="news-eml-file" type="file" accept=".eml,message/rfc822" ${ui.pending?'disabled':''}></div></div><div class="field"><label for="news-import-text">Newsletter content</label><textarea id="news-import-text" name="text" rows="7" maxlength="100000" required ${ui.pending?'disabled':''}>${esc(ui.draft.text)}</textarea></div><button class="button secondary" ${ui.pending?'disabled':''}>Summarize this newsletter</button></form><p class="form-help">Attachments are skipped. Pasted or exported Outlook email works; direct Outlook connection and publisher logins are not connected. Imported summaries remain private to your account.</p></div></section>
<div class="news-privacy"><h3>About your news</h3><p>BRB summarizes emails you receive. It does not sign in to WSJ or PitchBook or retrieve paywalled articles. No sample headlines are displayed.</p>${mailbox.coverageWarning?`<p>${esc(mailbox.coverageWarning)}</p>`:''}${news.retention?`<p>${esc(news.retention)}</p>`:''}${news.warnings?.length?`<ul>${news.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</div></div></details></section>`;
}
function refreshNews(){if(page==='news'&&state)render();}
async function newsRequest(operation,data){const ui=newsUI,owner=session;if(ui.pending||!owner?.user)return;const current=()=>session===owner&&newsUI===ui;ui.pending=true;ui.error='';ui.notice='';refreshNews();const finish=async(message,error=false)=>{if(!current())return;await load(false);if(!current())return;ui.pending=false;if(!error&&['settings','automatic'].includes(operation))ui.sourceDraft=null;ui[error?'error':'notice']=message;refreshNews();};try{if(!['connect','labels','select','sync','import','settings','disconnect','automatic'].includes(operation))throw new Error('Unknown news action.');if(operation==='automatic'&&(!state.news?.mailbox?.connected||state.profile.paused||!Array.isArray(data?.sources)||!data.sources.length||data.sources.some(id=>!newsProviders.some(p=>p.id===id))))throw new Error(state.profile.paused?'Resume your assistant before reading email.':!state.news?.mailbox?.connected?'Connect your Google email first.':'Choose at least one newsletter.');if(operation==='import'&&!newsProviders.some(p=>p.id===data.provider))throw new Error('Choose WSJ The 10-Point or PitchBook Daily Pitch.');if(operation==='select'&&!ui.labels.some(label=>label.id===data.labelId))throw new Error('Choose a custom label from your mailbox.');const result=await api(`/api/news/${operation}`,operation==='labels'?undefined:data||{});if(!current())return;if(operation==='connect'){ui.pending=false;location.href=result.url;return;}if(operation==='labels'){ui.advancedOpen=true;ui.labels=Array.isArray(result)?result:result.labels||[];ui.pending=false;ui.notice=ui.labels.length?'Choose a dedicated news label, separate from your event label.':'No custom labels found. Create one in Gmail and try again.';refreshNews();return;}if(operation==='import')ui.draft={provider:ui.draft.provider,name:'',text:'',format:'text'};if(operation==='disconnect')ui.labels=[];
if(result.taskId){ui.notice='Your newsletter search is queued. Briefings appear when processing finishes.';refreshNews();const start=Date.now();let polling=false;const timer=setInterval(async()=>{if(!current()){clearInterval(timer);return;}if(polling)return;polling=true;try{const tasks=await api('/api/tasks');if(!current()){clearInterval(timer);return;}const task=tasks.find(t=>t.id===result.taskId);if(['completed','done','failed','error','needs_review'].includes(task?.status)){clearInterval(timer);await finish(task.error||(['failed','error','needs_review'].includes(task.status)?'News processing needs attention. Check the source and try again.':task.result?.matched===0?'No matching newsletters found in the recent search. Check your subscriptions and connected inbox.':task.result?.processed===0?'Checked your newsletters. The latest available editions are already saved.':'Your newsletter briefings are ready.'),['failed','error','needs_review'].includes(task.status));}else if(Date.now()-start>240000){clearInterval(timer);await finish('News processing is still running. Check back shortly.',true);}}catch{clearInterval(timer);if(current()){ui.pending=false;ui.error='The connection was interrupted. Your queued newsletter request remains stored.';refreshNews();}}finally{polling=false;}},1500);return;}await finish(operation==='settings'?'Publisher choices saved. Telegram delivery choices are separate.':operation==='disconnect'?'News monitoring stopped. Saved summaries remain in your workspace.':'News source updated.');}catch(error){if(current()){ui.pending=false;ui.error=error.message;refreshNews();}}}
async function readNewsEmailFile(file){if(!file)return;const ui=newsUI,owner=session;if(ui.pending)return;if(!/\.eml$/i.test(file.name)||file.size>100000){ui.error='Choose an .eml file no larger than 100 KB.';refreshNews();return;}ui.pending=true;ui.error='';refreshNews();try{const text=await file.text();if(newsUI!==ui||session!==owner)return;if(text.length>100000)throw new Error('The exported email is larger than 100 KB.');ui.draft={...ui.draft,name:file.name,text,format:'eml'};ui.pending=false;ui.notice='Email loaded for review. Choose its publisher, then summarize when ready.';refreshNews();}catch(error){if(newsUI===ui&&session===owner){ui.pending=false;ui.error=error.message;refreshNews();}}}

function pilotAccessView(){
 if(!session?.pilotAccessAdmin)return '';
 const p=pilotAccessStatus||{},label=p.stale?'Sync overdue':p.active?'Sheet active':p.connected?'Needs first sync':'Setup required';
 return `<section class="panel" id="pilot-access"><div class="panel-head"><h2>Pilot invitations</h2><span class="tag ${p.active&&!p.stale?'green':'amber'}">${esc(label)}</span></div><div class="panel-body"><p>Manage Cornell invitations in your private approval sheet. Use <strong>Email</strong> and <strong>Access</strong> columns, with <strong>Approved</strong> or <strong>Revoked</strong>. After the first successful sync, removing a row also removes access.</p><p class="form-help">Checked every minute while the server runs. ${p.active?`${esc(p.approvedCount)} approved accounts. Last successful sync: ${esc(new Date(p.lastSuccess).toLocaleString())}.`:'Your existing pilot list stays active until the first successful sync.'} Your operator account retains recovery access.</p>${p.error?`<p class="course-error" role="alert">${esc(p.error)}</p>`:''}${p.stale?'<p class="notice">The sheet has not refreshed for 15 minutes. Student access is blocked until sync recovers; the operator can reconnect here.</p>':''}<div class="form-actions">${btn(p.connected?'Reconnect approval sheet':'Connect approval sheet','connect-pilot-sheet')}${p.connected?btn('Sync invitations now','sync-pilot-sheet','secondary'):''}${p.sheetURL?`<a class="button quiet" href="${link(p.sheetURL)}" target="_blank" rel="noopener noreferrer">Open approval sheet ↗</a>`:''}</div><p class="form-help">Owner-only connection. Google grants read access to all your spreadsheets; BRB reads only the configured approval sheet. Enable Google Sheets API before connecting. Keep this sheet private and restrict who can edit it. While Google OAuth is in Testing, also add invited students under Google Auth Platform → Audience → Test users.</p></div></section>`;
}
function connections(){const c=state.connections,t=c.telegram,g=c.google,s=c.slack;return heading('YOUR ACCOUNTS. YOUR WORKSPACE.','Connect once. Stay in sync.','Authorize your own accounts. Your credentials and imported content belong to your student workspace.')+pilotAccessView()+dailyBriefingView()+notificationsView()+remindersView()+
 `<div class="integration-grid"><section class="panel"><div class="panel-head"><h2>Telegram</h2><span class="tag ${t.linked?'green':'amber'}">${t.linked?'Account linked':t.configured?'Ready to link':'Operator setup pending'}</span></div><div class="panel-body"><p>Everyone uses the same Big Red Buddy bot. Your private chat is linked only to your student account.</p><p class="form-help">Photos and PDFs: send <code>/syllabus FA26</code> for assignment deadlines or <code>/enrollment FA26</code> for class schedules, then attach your document. Use <code>SP27</code> for Spring 2027. The bot shows a review before you confirm calendar additions.</p>${t.linkCode?`<div class="link-code"><a class="button" href="https://t.me/${esc(t.bot)}?start=${esc(t.linkCode)}" target="_blank" rel="noreferrer">Open Telegram and connect ↗</a><p class="form-help">One-time link. Expires after 15 minutes.</p></div>`:''}<div class="form-actions">${t.configured?btn(t.linked?'Relink Telegram':'Connect my Telegram','telegram-link'):''}${t.linked?btn('Send test','telegram-test','secondary small')+btn('Send my week','telegram-brief','secondary small')+btn('Disconnect','disconnect','quiet','data-service="telegram"'):''}</div><p class="form-help">@${esc(t.bot)} · /today · /week · /pause · /resume<br>${esc(t.health?.error||'Reminder delivery runs separately from AI generation.')}</p></div></section>
 <section class="panel"><div class="panel-head"><h2>Google Calendar</h2><span class="tag ${g.connected?'green':'amber'}">${g.connected?'Connected':'Not connected'}</span></div><div class="panel-body"><p>Connect your Cornell Google account to add reviewed dates to a dedicated assistant calendar.</p><p class="form-help">Requests access to calendars created by this app. No inbox access is requested.</p><div class="form-actions">${g.configured?btn(g.connected?'Reconnect Google':'Connect my Google Calendar','connect-google'):'<p class="notice">The operator needs to configure Google OAuth.</p>'}${g.connected?btn('Sync reviewed items','sync-google','secondary')+btn('Disconnect','disconnect','quiet','data-service="google"'):''}</div><p class="form-help">Cornell may require approval for this app. ${g.health?.lastSuccess?'Last synced '+esc(new Date(g.health.lastSuccess).toLocaleString()):'No successful calendar sync yet.'}</p></div></section>
 <section class="panel"><div class="panel-head"><h2>Product Studio Slack</h2><span class="tag ${s.configured?'green':'amber'}">${s.configured?'Account connected':'Not connected'}</span></div><div class="panel-body"><p>Authorize your own Slack account, then select a channel you belong to.</p><div class="form-actions">${s.available?btn(s.configured?'Reconnect Slack':'Connect my Slack','connect-slack'):'<p class="notice">Slack app installation and workspace approval are pending.</p>'}</div>${s.configured?`<form id="slack-channel-form"><div class="field"><label for="slack-channel">Channel ID</label><input id="slack-channel" name="channel" value="${esc(s.channel)}" placeholder="C0BSGSNHM5J" required></div><button class="button secondary">Verify channel membership</button></form><div class="form-actions">${btn('Refresh announcements','sync-slack','secondary small')}${btn('Disconnect','disconnect','quiet','data-service="slack"')}</div>`:''}<p class="form-help">New selected announcements can alert your linked Telegram chat. Dates need your review. Reads are paged, with a recent overlap for edits; older changes may need manual review. ${s.health?.moreAvailable?'More history remains to be imported.':''} ${esc(s.health?.warning||'')}</p></div></section>
 <section class="panel"><div class="panel-head"><h2>Privacy & reminders</h2><span class="tag">YOUR WORKSPACE</span></div><div class="panel-body"><p>Your documents use the shared private model, with only your sources included in each request.</p><p class="form-help">We retain your resume, schedules, source excerpts, preferences, account connections, application drafts, delivery records, and any optional self-identification preferences you explicitly save. Credentials and content are encrypted in storage. Hosting operators with privileged access can still access processed data. Temporary queued requests and answers expire after 24 hours.</p><div class="form-actions">${btn(state.profile.paused?'Resume reminders':'Pause reminders','toggle-pause','secondary small')}${btn('Check service status','health','secondary small')}</div><p class="form-help">${health?.mode?esc(health.mode):'Checking deployment'} · ${health?.storage?esc(health.storage):''}<br>Last reminder check: ${c.scheduler?.lastRun?esc(new Date(c.scheduler.lastRun).toLocaleString()):'No worker check recorded yet'}</p><div class="form-actions">${btn('Delete my assistant data','delete-data','danger small')}${btn('Sign out','logout','secondary small')}</div><p class="form-help">Deletion permanently closes this pilot account and removes its active assistant content and connections. External calendars, Telegram messages, original documents, and backup retention remain separate.</p></div></section></div>`;}
function evidence(){const metrics=state.metrics.filter(m=>m.ms>0),average=metrics.length?Math.round(metrics.reduce((a,m)=>a+m.ms,0)/metrics.length):null;const sent=state.reminders.filter(r=>r.status==='sent').length;return heading('SHOW THE WORK','Evidence over promises.','Measured behavior, explicit gaps, and an honest view of what this prototype costs.',`<a class="button secondary" href="/api/evaluation.json">↓ Export evaluation data</a>`)+
    `<div class="summary-grid"><div class="stat"><div class="stat-top">Local model runs</div><div class="stat-value">${metrics.length}</div><div class="stat-bottom">Actual completed requests</div></div><div class="stat"><div class="stat-top">Mean model request time</div><div class="stat-value">${average===null?'—':(average/1000).toFixed(1)}<span>seconds</span></div><div class="stat-bottom">Includes observed load and generation</div></div><div class="stat"><div class="stat-top">Telegram accepted</div><div class="stat-value">${sent}</div><div class="stat-bottom">Acceptance does not establish message seen</div></div><div class="stat"><div class="stat-top">Deadline accuracy</div><div class="stat-value">—</div><div class="stat-bottom">No independent corpus evaluation yet</div></div></div>
    <section class="panel"><div class="panel-head"><h2>Your processing & delivery</h2><span class="tag">MEASURED</span></div><div class="panel-body"><table class="economics-table"><tbody><tr><td>Queue delay · p95, last 24 hours</td><td>${state.capacity?.queue.queueDelayP95Ms==null?'No samples':(state.capacity.queue.queueDelayP95Ms/1000).toFixed(2)+' s'}</td></tr><tr><td>Model latency · p95, last 30 days</td><td>${state.capacity?.model.latencyP95Ms==null?'No samples':(state.capacity.model.latencyP95Ms/1000).toFixed(2)+' s'}</td></tr><tr><td>Reminder lateness · p95</td><td>${state.capacity?.reminders.latenessP95Ms==null?'No accepted reminders yet':(state.capacity.reminders.latenessP95Ms/1000).toFixed(2)+' s'}</td></tr><tr><td>Queued / running jobs</td><td>${state.capacity?.queue.counts.queued||0} / ${state.capacity?.queue.counts.running||0}</td></tr><tr><td>Failed or uncertain jobs · last 24 hours</td><td>${(state.capacity?.queue.counts.failed||0)+(state.capacity?.queue.counts.needs_review||0)}</td></tr><tr><td>Missed / uncertain reminders</td><td>${state.capacity?.reminders.missed||0} / ${state.capacity?.reminders.uncertain||0}</td></tr></tbody></table><p class="form-help">Measured from your own jobs and delivery attempts. Empty samples are not a claim of zero latency or perfect reliability. Shared infrastructure cost per active student is available to the operator after actual expenses are entered.</p></div></section>
    <div class="split"><section class="panel"><div class="panel-head"><h2>Unit economics sandbox</h2><span class="tag amber">ASSUMPTIONS</span></div><div class="panel-body"><p class="subtitle">Editable inputs. These are scenario assumptions, not provider quotes or measured production costs.</p><form id="economics-form"><div class="form-grid"><div><label for="eco-fixed">Monthly shared infrastructure · $</label><input id="eco-fixed" name="fixed" type="number" min="0" value="100"></div><div><label for="eco-users">Active students</label><input id="eco-users" name="users" type="number" min="1" value="10"></div><div><label for="eco-variable">Other variable cost / student · $</label><input id="eco-variable" name="variable" type="number" min="0" step="0.01" value="0"></div><div><label for="eco-price">Hypothetical monthly price · $</label><input id="eco-price" name="price" type="number" min="0" value="15"></div><div><label for="eco-hours">Assumed monthly hours saved</label><input id="eco-hours" name="hours" type="number" min="0" step="0.5" value="2"></div><div><label for="eco-value">Assumed value of an hour · $</label><input id="eco-value" name="value" type="number" min="0" value="20"></div></div></form><div id="economics-result"></div><p class="form-help">Excludes engineering time, support, hardware depreciation, payment fees, licensing, and changes in inference capacity. Time savings and willingness to pay require student testing. Local models have compute costs even without token charges.</p></div></section><section class="panel"><div class="panel-head"><h2>What is implemented</h2></div><div class="panel-body"><div class="activity-row"><span>Source-specific syllabus parser, generic local-model extraction, evidence review, and .ics export.</span></div><div class="activity-row"><span>Google sign-in and calendar authorization, one shared Telegram bot with individual chat links, and Slack account authorization. Live access requires operator setup.</span></div><div class="activity-row"><span>Employer-board job discovery, resume-based matching and new-role alerts, local drafting, and reviewed submission to a local sandbox.</span></div><div class="activity-row"><span>Campus event snapshots and optional subscribed-Google-calendar monitoring, with signup links and explicit calendar additions.</span></div><div class="activity-row"><span>Student ownership, PostgreSQL row-level isolation, encrypted storage, durable job workers, and capacity measurements. Enrollment PDF/photo recognition proposes catalog matches for individual selection and confirmation. Live employer submission remains unimplemented.</span></div><p class="form-help">Your proposal’s 98% precision / 95% recall and 50% time-saving goals remain targets, not results.</p></div></section></div>
    <section class="panel"><div class="panel-head"><h2>Activity, without the payloads</h2><span class="tag">CONTENT-LIMITED LOG</span></div><div class="panel-body">${state.activity.map(a=>`<div class="activity-row"><span>${esc(a.detail)}</span><time>${new Date(a.at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</time></div>`).join('')||'<p class="subtitle">No activity yet.</p>'}</div></section>`;}
function render(){const requested=location.hash.slice(1)||'overview';page=requested==='demographics'?'careers':requested;if(requested==='demographics'&&!demographicsUI.deepLinkHandled){careerBrowserUI.tab='profile';demographicsUI.focusRequested=true;demographicsUI.deepLinkHandled=true;}if(!names[page])page='overview';document.querySelectorAll('nav [aria-current]').forEach(el=>el.removeAttribute('aria-current'));document.querySelector(`[data-page="${page}"]`)?.setAttribute('aria-current','page');$('#breadcrumb').textContent=names[page];$('#today-label').textContent=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',weekday:'short',month:'short',day:'numeric'}).format(new Date(state.now));$('#academic-count').textContent=state.events.filter(e=>['class','assignment','quiz','exam'].includes(e.kind)&&e.date>=currentDate()).length;$('nav a.active')?.classList.remove('active');document.querySelector(`[data-page="${page}"]`)?.classList.add('active');$('#main').innerHTML=({overview,academics,studio,events:eventsPage,careers,news:newsPage,connections,evidence}[page])();if(page==='evidence')economics();if(page==='academics'&&!enrollment.loaded&&!enrollment.loading)fetchEnrollmentProposals();if(page==='careers'&&careerBrowserUI.tab==='profile')loadDemographics();}
function economics(){const f=$('#economics-form');if(!f)return;const b=Object.fromEntries(new FormData(f));const cost=+b.fixed/Math.max(1,+b.users)+ +b.variable,margin=+b.price?((+b.price-cost)/+b.price*100):null;$('#economics-result').innerHTML=`<table class="economics-table"><tbody><tr><td>Estimated monthly cost / student</td><td><strong>$${cost.toFixed(2)}</strong></td></tr><tr><td>Contribution margin before excluded costs</td><td>${margin===null?'—':margin.toFixed(1)+'%'}</td></tr><tr><td>Assumed monthly student time value</td><td>$${(+b.hours*+b.value).toFixed(2)}</td></tr></tbody></table>`;}
function detail(id){const e=state.events.find(e=>e.id===id);if(!e)return;$('#detail-content').innerHTML=`<div class="eyebrow">SOURCE-BACKED REVIEW</div><h2 id="detail-title">${esc(e.title)}</h2><p class="subtitle">${fullDate(e)} · ${e.start?timeFmt.format(new Date(e.start))+' New York':'Time not specified'}</p><div class="detail-label">Source</div><p>${esc(e.sourceName)}${e.page?' · page '+e.page:''}</p><div class="detail-label">Supporting text</div><div class="evidence-text">${esc(e.evidence)}</div>${e.warning?`<div class="notice">${esc(e.warning)}</div>`:''}${e.sourceUrl?`<a class="button quiet" href="${link(e.sourceUrl)}" target="_blank" rel="noreferrer">Open original source ↗</a>`:''}${!e.start?`<form id="confirm-time" data-id="${e.id}" class="form-actions"><label for="confirmed-time">Time confirmed by you<input id="confirmed-time" name="time" type="time" required></label><button class="button secondary">Save time for review</button></form>`:''}<div class="form-actions">${e.start&&e.evidenceVerified!==false&&!e.cancelled?btn(e.status==='approved'?'Already approved':'Approve this item','approve-one','',`data-id="${e.id}" ${e.status==='approved'?'disabled':''}`):''}${e.cancelled?btn('Confirm calendar removal','cancel-one','secondary',`data-id="${e.id}"`):''}${btn('Dismiss','dismiss-one','secondary',`data-id="${e.id}"`)}</div>`;$('#detail-dialog').showModal();}
function syllabusUploadView(){const ui=syllabusUI,term=ui.term||coursePicker.term||'FA26';return `<section id="syllabus-upload-area" class="syllabus-upload-area" aria-labelledby="syllabus-upload-heading"><div class="course-syllabus-step"><div><h2 id="syllabus-upload-heading">Add your syllabus deadlines</h2><p>Upload a PDF or a clear JPG/PNG photo of assignments, quizzes, and exams.</p><p class="form-help">Up to 12 MB. PDFs: up to 6 pages, including up to 4 scanned pages. Include dates and deadline rules. For iPhone HEIC files, export a JPG first.</p></div><div class="syllabus-upload-controls"><div><label for="syllabus-term">Syllabus term</label><select id="syllabus-term" ${ui.pending?'disabled':''}><option value="FA26" ${term==='FA26'?'selected':''}>Fall 2026</option><option value="SP27" ${term==='SP27'?'selected':''}>Spring 2027</option></select></div><div class="form-actions">${btn(ui.pending?'Processing…':'Upload PDF or photo','upload-syllabus','secondary',ui.pending?'disabled':'')}${btn('Take a photo','camera-syllabus','quiet',ui.pending?'disabled':'')}</div></div></div><div id="syllabus-upload-status" role="status" aria-live="polite">${ui.pending?`<p>Reading ${esc(ui.name)} and finding deadline dates. You can keep using your workspace.</p>`:''}${ui.error?`<p class="course-error">${esc(ui.error)}</p>`:''}${ui.notice?`<p>${esc(ui.notice)}</p><a href="#academics" data-filter="review">Review extracted dates →</a>`:''}</div></section>`;}
function refreshSyllabusUpload(){if(page==='academics'&&state){const element=$('#syllabus-upload-area');if(element)element.outerHTML=syllabusUploadView();}}
async function uploadSyllabus(file){
 if(!file||syllabusUI.pending||!session?.user)return;
 const ui=syllabusUI,owner=session,term=ui.term||coursePicker.term||'FA26';ui.error='';ui.notice='';
 try{
  if(!Number.isFinite(file.size)||file.size<1||file.size>12*1024*1024)throw new Error('Choose a nonempty syllabus file up to 12 MB.');
  const extension=String(file.name||'').split('.').at(-1).toLowerCase();
  const declared=String(file.type||'').toLowerCase(),mimeType=declared==='image/jpg'?'image/jpeg':declared||({pdf:'application/pdf',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png'}[extension]);
  if(!['application/pdf','image/jpeg','image/png'].includes(mimeType))throw new Error('Use a PDF, JPG, or PNG. For an iPhone HEIC photo, export it as JPG first.');
  ui.pending=true;ui.name=file.name;refreshSyllabusUpload();
  const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('This file could not be opened. Choose it again.'));reader.readAsDataURL(file);});
  if(session!==owner||syllabusUI!==ui)return;
  const result=await api('/api/upload',{type:'syllabus',name:file.name,base64,mimeType,term});
  if(session!==owner||syllabusUI!==ui)return;
  toast('Syllabus queued. Dates will appear for review.');
  watchFeatureTask(result.taskId,{active:()=>session===owner&&syllabusUI===ui&&ui.pending,onDone:async result=>{
   await load(false);if(session!==owner||syllabusUI!==ui)return;ui.pending=false;ui.notice=`${Number(result?.count)||0} deadline dates are ready for review. Check dates and missing times before approving them.`;filter='review';if(page==='academics')render();else toast(ui.notice);
  },onError:message=>{if(session!==owner||syllabusUI!==ui)return;ui.pending=false;ui.error=message;refreshSyllabusUpload();toast(message,true);}});
 }catch(error){if(session!==owner||syllabusUI!==ui)return;ui.pending=false;ui.error=error.message||'Syllabus upload failed. Please try again.';refreshSyllabusUpload();toast(ui.error,true);}
}
async function upload(file,type){if(type==='syllabus')return uploadSyllabus(file);if(!file)return;const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await runTask('/api/upload',{type,name:file.name,base64});}
