 if(a==='upload-enrollment'||a==='camera-enrollment'){if(!['FA26','SP27'].includes(enrollment.term)){enrollment.error='Choose the term shown on your enrollment document first.';refreshEnrollmentView('enrollment-term');return;}$(a==='camera-enrollment'?'#enrollment-camera':'#enrollment-file').click();return;}
 if(a==='refresh-enrollment'){fetchEnrollmentProposals();return;}
 if(a==='confirm-enrollment'){confirmEnrollment(id);return;}
