 if(a==='hub-details'){hubDetails(id);return;}
 if(a==='setup-event-email'){const provider=target.dataset.provider;if(!['luma','partiful'].includes(provider))return;const c=state.eventEmail||{},previous=eventHubUI.emailAutomaticDraft;eventHubUI.emailAutomaticDraft={providers:[...new Set([...(previous?.providers||c.providers||[]),provider])],autoAdd:previous?.autoAdd??c.autoAdd===true};eventHubUI.sourcesOpen=true;render();document.getElementById('event-email-automatic')?.scrollIntoView?.({block:'start'});document.getElementById('event-email-provider-'+provider)?.focus();return;}
 if(a==='hub-calendar-day'){eventCalendarSelect(target.dataset.date,{focus:true});return;}
 if(a==='hub-calendar-month'){const offset=Number(target.dataset.offset);if(![-1,1].includes(offset))return;const month=eventCalendarMonthShift(eventHubUI.calendarMonth||(eventHubUI.calendarDate||currentDate()).slice(0,7),offset);if(month){eventCalendarSelect(month+'-01');$(`[data-action="hub-calendar-month"][data-offset="${offset}"]`)?.focus();}return;}
 if(a==='hub-calendar-today'){eventCalendarSelect(currentDate());$('[data-action="hub-calendar-today"]')?.focus();return;}
 if(a==='hub-calendar-agenda'){eventHubUI.range='day';refreshEventHub();const agenda=$('#event-hub .event-agenda');if(agenda){agenda.setAttribute('tabindex','-1');agenda.focus();agenda.scrollIntoView?.({block:'start'});}return;}
 if(a==='hub-add'){const item=(state.eventHub?.items||[]).find(row=>row.id===id);if(!item||eventHubUI.pending)return;const record=state.events.find(e=>e.id===item.action?.id),payload={id,revision:target.dataset.revision||''};if(['email','manual'].includes(item.action?.kind)&&record?.start&&(!record.end||Date.parse(record.end)<=Date.parse(record.start))){const input=$('#hub-event-duration');if(!input){hubDetails(id);return;}const value=Number(input.value);if(!input.value||!Number.isInteger(value)||value<1||value>1440){$('#hub-duration-error').textContent='Enter a duration from 1 to 1440 minutes.';input.focus();return;}payload.durationMinutes=value;}if($('#detail-dialog').open)$('#detail-dialog').close();eventHubRequest('/api/event-hub/add',payload,'Event saved in your assistant schedule. Check its calendar sync status; registration is separate.');return;}
 if(['hub-range','hub-source','hub-category'].includes(a)){const field=a.slice(4);eventHubUI[field]=target.dataset.value;refreshEventHub();return;}
 if(a==='hub-reset'){Object.assign(eventHubUI,{query:'',range:'all',source:'all',category:'all'});refreshEventHub();return;}
 if(a==='hub-manage'){eventHubUI.sourcesOpen=true;const el=$('#event-sources');if(el){el.open=true;el.scrollIntoView?.({block:'start'});}return;}
 if(a==='hub-academic'){Object.assign(eventHubUI,{source:'academic',range:'all',category:'all',query:''});refreshEventHub();$('#event-hub')?.scrollIntoView?.({block:'start'});return;}
 if(a==='academic-refresh'){eventHubRequest('/api/academic/refresh',{},'Official Cornell dates refreshed. Select the dates you want to add.',{queued:true});return;}
 if(['connect-event-email','list-event-email','sync-event-email','stop-event-email','disconnect-event-email'].includes(a)){eventEmailAction(a);return;}
