 if(a==='reset-notifications'){notificationsUI.draft=null;notificationsUI.error='';notificationsUI.notice='';refreshNotifications();return;}
 if(a==='save-news-sources'){newsRequest('settings',{sources:newsProviders.filter(provider=>notificationChecked(document.getElementById('news-source-'+provider.id))).map(provider=>provider.id)});return;}
 if(['connect-news','list-news-labels','sync-news','disconnect-news'].includes(a)){newsRequest({'connect-news':'connect','list-news-labels':'labels','sync-news':'sync','disconnect-news':'disconnect'}[a]);return;}
 if(['connect-luma','list-luma','sync-luma','disconnect-luma','add-luma'].includes(a)){lumaAction({'connect-luma':'connect','list-luma':'calendars','sync-luma':'sync','disconnect-luma':'disconnect','add-luma':'add'}[a],a==='add-luma'?{id}:{});return;}
 if(a==='career-more-jobs'){const firstNewIndex=careerBrowserUI.visibleCount;careerBrowserUI.visibleCount+=40;const el=$('#discovered-jobs');if(el)el.outerHTML=discoveredJobsView();const firstNew=document.querySelectorAll('[data-action="career-select-job"]')[firstNewIndex];if(firstNew)firstNew.focus();else{const heading=$('#career-results-heading');if(heading){heading.setAttribute('tabindex','-1');heading.focus();}}return;}
 if(a==='draft-job'){prepareCareerApplication(id);return;}
 if(a==='career-tab'){setCareerTab(target.dataset.tab,{focus:true});return;}
 if(a==='career-select-job'){if(!careerJobRows().some(job=>job.id===id))return;careerBrowserUI.selectedId=id;careerBrowserUI.mobileDetail=true;const el=$('#discovered-jobs');if(el)el.outerHTML=discoveredJobsView();$('#career-detail-heading')?.focus();return;}
 if(a==='career-job-back'){careerBrowserUI.mobileDetail=false;const el=$('#discovered-jobs');if(el)el.outerHTML=discoveredJobsView();[...document.querySelectorAll('[data-action="career-select-job"]')].find(button=>button.dataset.id===careerBrowserUI.selectedId)?.focus();return;}
 if(a==='career-save-job'){saveCareerJob(id);return;}
 if(a==='career-clear-filters'){careerBrowserUI.filters=emptyCareerBrowserUI().filters;careerBrowserUI.mobileDetail=false;careerBrowserUI.visibleCount=40;careerBrowserUI.selectedId='';jobRecency=careerBrowserUI.jobTab==='saved'?'all':'week';careerBrowserUI.recencies[careerBrowserUI.jobTab]=jobRecency;const el=$('#discovered-jobs');if(el)el.outerHTML=discoveredJobsView();return;}
 if(a==='job-recency'){jobRecency=['24h','week','all','undated'].includes(target.dataset.value)?target.dataset.value:'week';careerBrowserUI.recencies[careerBrowserUI.jobTab]=jobRecency;careerBrowserUI.mobileDetail=false;careerBrowserUI.visibleCount=40;careerBrowserUI.selectedId='';const el=$('#discovered-jobs');if(el)el.outerHTML=discoveredJobsView();return;}
